const LEVELS = [{"id": 1, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "People & Greetings", "focus": "First words for meeting people", "type": "vocab", "intro": "Welcome to your very first level. You do not need to know any English yet — we start from zero. Learn these words out loud, several times, before moving on.", "items": [{"a": "hello", "b": "heh-LOH", "c": "greeting", "d": "a friendly word you say when you meet someone", "e": "Hello, my name is Ravi."}, {"a": "name", "b": "NAYM", "c": "noun", "d": "what people call you", "e": "My name is Priya."}, {"a": "friend", "b": "FREND", "c": "noun", "d": "a person you like and trust", "e": "She is my friend."}, {"a": "please", "b": "PLEEZ", "c": "polite word", "d": "used to ask for something kindly", "e": "Please sit down."}, {"a": "thank you", "b": "THANK-yoo", "c": "polite phrase", "d": "used to show you are grateful", "e": "Thank you for your help."}, {"a": "sorry", "b": "SOR-ee", "c": "polite word", "d": "used when you made a mistake", "e": "Sorry, I am late."}], "tip": "Open your mouth wide for the 'h' sound in 'hello' — say it like a soft breath, not a hard cough.", "speaking": "Say this out loud: 'Hello, my name is ___. Thank you.' Record yourself and listen back.", "quiz": [{"type": "mcq", "q": "What does \"hello\" mean?", "options": ["a friendly word you say when you meet someone", "what people call you", "a person you like and trust", "used to ask for something kindly"], "answer": 0, "explanation": "\"hello\" means a friendly word you say when you meet someone."}, {"type": "mcq", "q": "What does \"name\" mean?", "options": ["what people call you", "a friendly word you say when you meet someone", "a person you like and trust", "used to ask for something kindly"], "answer": 0, "explanation": "\"name\" means what people call you."}, {"type": "mcq", "q": "What does \"friend\" mean?", "options": ["a person you like and trust", "a friendly word you say when you meet someone", "what people call you", "used to ask for something kindly"], "answer": 0, "explanation": "\"friend\" means a person you like and trust."}, {"type": "mcq", "q": "What does \"please\" mean?", "options": ["used to ask for something kindly", "a friendly word you say when you meet someone", "what people call you", "a person you like and trust"], "answer": 0, "explanation": "\"please\" means used to ask for something kindly."}, {"type": "fill", "q": "Thank you for your help.", "answer": "thank you", "explanation": "The word is \"thank you\" — used to show you are grateful."}, {"type": "fill", "q": "Sorry, I am late.", "answer": "sorry", "explanation": "The word is \"sorry\" — used when you made a mistake."}]}, {"id": 2, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "Family Words", "focus": "Talking about the people at home", "type": "vocab", "intro": "Family words are some of the most useful words you will ever learn — you use them almost every day.", "items": [{"a": "mother", "b": "MUH-ther", "c": "noun", "d": "your female parent", "e": "My mother cooks very well."}, {"a": "father", "b": "FAH-ther", "c": "noun", "d": "your male parent", "e": "My father works in a bank."}, {"a": "brother", "b": "BRUH-ther", "c": "noun", "d": "a boy with the same parents as you", "e": "I have one brother."}, {"a": "sister", "b": "SIS-ter", "c": "noun", "d": "a girl with the same parents as you", "e": "My sister is younger than me."}, {"a": "family", "b": "FAM-ih-lee", "c": "noun", "d": "the group of people related to you", "e": "I love my family."}, {"a": "child", "b": "CHYLD", "c": "noun", "d": "a young person", "e": "The child is playing outside."}], "tip": "Practise the 'th' sound in 'mother' and 'father' by placing your tongue lightly between your teeth.", "speaking": "Describe your family in three simple sentences using today's words.", "quiz": [{"type": "mcq", "q": "What does \"mother\" mean?", "options": ["your female parent", "your male parent", "a boy with the same parents as you", "a girl with the same parents as you"], "answer": 0, "explanation": "\"mother\" means your female parent."}, {"type": "mcq", "q": "What does \"father\" mean?", "options": ["your male parent", "your female parent", "a boy with the same parents as you", "a girl with the same parents as you"], "answer": 0, "explanation": "\"father\" means your male parent."}, {"type": "mcq", "q": "What does \"brother\" mean?", "options": ["a boy with the same parents as you", "your female parent", "your male parent", "a girl with the same parents as you"], "answer": 0, "explanation": "\"brother\" means a boy with the same parents as you."}, {"type": "mcq", "q": "What does \"sister\" mean?", "options": ["a girl with the same parents as you", "your female parent", "your male parent", "a boy with the same parents as you"], "answer": 0, "explanation": "\"sister\" means a girl with the same parents as you."}, {"type": "fill", "q": "I love my ____.", "answer": "family", "explanation": "The word is \"family\" — the group of people related to you."}, {"type": "fill", "q": "The ____ is playing outside.", "answer": "child", "explanation": "The word is \"child\" — a young person."}]}, {"id": 3, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "Numbers & Time", "focus": "Counting and talking about time", "type": "vocab", "intro": "You will use numbers and time words constantly — in shops, on the phone, and when making plans.", "items": [{"a": "number", "b": "NUHM-ber", "c": "noun", "d": "a word for counting, like one, two, three", "e": "What is your phone number?"}, {"a": "day", "b": "DAY", "c": "noun", "d": "24 hours; one turn of the sun", "e": "Today is a good day."}, {"a": "week", "b": "WEEK", "c": "noun", "d": "seven days", "e": "I work five days a week."}, {"a": "today", "b": "tuh-DAY", "c": "adverb", "d": "this day, right now", "e": "Today is Monday."}, {"a": "tomorrow", "b": "tuh-MOR-oh", "c": "adverb", "d": "the day after today", "e": "I will see you tomorrow."}, {"a": "morning", "b": "MOR-ning", "c": "noun", "d": "the early part of the day", "e": "Good morning!"}], "tip": "Stress the middle syllable in 'tomorrow': tuh-MOR-oh, not TOM-or-oh.", "speaking": "Say: 'Today is ___. Tomorrow I will ___.' Fill in your own real plans.", "quiz": [{"type": "mcq", "q": "What does \"number\" mean?", "options": ["a word for counting, like one, two, three", "24 hours; one turn of the sun", "seven days", "this day, right now"], "answer": 0, "explanation": "\"number\" means a word for counting, like one, two, three."}, {"type": "mcq", "q": "What does \"day\" mean?", "options": ["24 hours; one turn of the sun", "a word for counting, like one, two, three", "seven days", "this day, right now"], "answer": 0, "explanation": "\"day\" means 24 hours; one turn of the sun."}, {"type": "mcq", "q": "What does \"week\" mean?", "options": ["seven days", "a word for counting, like one, two, three", "24 hours; one turn of the sun", "this day, right now"], "answer": 0, "explanation": "\"week\" means seven days."}, {"type": "mcq", "q": "What does \"today\" mean?", "options": ["this day, right now", "a word for counting, like one, two, three", "24 hours; one turn of the sun", "seven days"], "answer": 0, "explanation": "\"today\" means this day, right now."}, {"type": "fill", "q": "I will see you ____.", "answer": "tomorrow", "explanation": "The word is \"tomorrow\" — the day after today."}, {"type": "fill", "q": "Good ____!", "answer": "morning", "explanation": "The word is \"morning\" — the early part of the day."}]}, {"id": 4, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "Colors & Shapes", "focus": "Describing what things look like", "type": "vocab", "intro": "Colors and shapes help you describe almost anything you see.", "items": [{"a": "red", "b": "RED", "c": "adjective", "d": "the color of blood or a tomato", "e": "The apple is red."}, {"a": "blue", "b": "BLOO", "c": "adjective", "d": "the color of the sky", "e": "The sky is blue."}, {"a": "green", "b": "GREEN", "c": "adjective", "d": "the color of grass", "e": "The grass is green."}, {"a": "black", "b": "BLAK", "c": "adjective", "d": "the darkest color", "e": "My bag is black."}, {"a": "big", "b": "BIG", "c": "adjective", "d": "large in size", "e": "That is a big house."}, {"a": "small", "b": "SMAWL", "c": "adjective", "d": "little in size", "e": "The kitten is small."}], "tip": "Keep vowel sounds short and clean: 'big' is one quick sound, not 'bee-ig'.", "speaking": "Look around the room and describe three objects using color and size words.", "quiz": [{"type": "mcq", "q": "What does \"red\" mean?", "options": ["the color of blood or a tomato", "the color of the sky", "the color of grass", "the darkest color"], "answer": 0, "explanation": "\"red\" means the color of blood or a tomato."}, {"type": "mcq", "q": "What does \"blue\" mean?", "options": ["the color of the sky", "the color of blood or a tomato", "the color of grass", "the darkest color"], "answer": 0, "explanation": "\"blue\" means the color of the sky."}, {"type": "mcq", "q": "What does \"green\" mean?", "options": ["the color of grass", "the color of blood or a tomato", "the color of the sky", "the darkest color"], "answer": 0, "explanation": "\"green\" means the color of grass."}, {"type": "mcq", "q": "What does \"black\" mean?", "options": ["the darkest color", "the color of blood or a tomato", "the color of the sky", "the color of grass"], "answer": 0, "explanation": "\"black\" means the darkest color."}, {"type": "fill", "q": "That is a ____ house.", "answer": "big", "explanation": "The word is \"big\" — large in size."}, {"type": "fill", "q": "The kitten is ____.", "answer": "small", "explanation": "The word is \"small\" — little in size."}]}, {"id": 5, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "Body Parts", "focus": "Talking about your body", "type": "vocab", "intro": "Body words are essential for describing feelings, health, and appearance.", "items": [{"a": "head", "b": "HED", "c": "noun", "d": "the top part of your body", "e": "My head hurts."}, {"a": "eye", "b": "EYE", "c": "noun", "d": "the part of your face you see with", "e": "She has brown eyes."}, {"a": "hand", "b": "HAND", "c": "noun", "d": "the part at the end of your arm", "e": "Wash your hands."}, {"a": "leg", "b": "LEG", "c": "noun", "d": "the part of your body you walk with", "e": "He hurt his leg."}, {"a": "face", "b": "FAYSS", "c": "noun", "d": "the front part of your head", "e": "Wash your face."}, {"a": "hair", "b": "HAIR", "c": "noun", "d": "what grows on your head", "e": "Her hair is long."}], "tip": "Say 'hair' and 'hear' — notice the small difference in mouth shape.", "speaking": "Point to a body part and name it out loud, five times, at natural speed.", "quiz": [{"type": "mcq", "q": "What does \"head\" mean?", "options": ["the top part of your body", "the part of your face you see with", "the part at the end of your arm", "the part of your body you walk with"], "answer": 0, "explanation": "\"head\" means the top part of your body."}, {"type": "mcq", "q": "What does \"eye\" mean?", "options": ["the part of your face you see with", "the top part of your body", "the part at the end of your arm", "the part of your body you walk with"], "answer": 0, "explanation": "\"eye\" means the part of your face you see with."}, {"type": "mcq", "q": "What does \"hand\" mean?", "options": ["the part at the end of your arm", "the top part of your body", "the part of your face you see with", "the part of your body you walk with"], "answer": 0, "explanation": "\"hand\" means the part at the end of your arm."}, {"type": "mcq", "q": "What does \"leg\" mean?", "options": ["the part of your body you walk with", "the top part of your body", "the part of your face you see with", "the part at the end of your arm"], "answer": 0, "explanation": "\"leg\" means the part of your body you walk with."}, {"type": "fill", "q": "Wash your ____.", "answer": "face", "explanation": "The word is \"face\" — the front part of your head."}, {"type": "fill", "q": "Her ____ is long.", "answer": "hair", "explanation": "The word is \"hair\" — what grows on your head."}]}, {"id": 6, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "Food & Drink", "focus": "Ordering and describing food", "type": "vocab", "intro": "You will need these words in restaurants, kitchens, and shops.", "items": [{"a": "water", "b": "WAH-ter", "c": "noun", "d": "a clear drink everyone needs", "e": "Please give me some water."}, {"a": "rice", "b": "RYSS", "c": "noun", "d": "a common food made of small white grains", "e": "We eat rice every day."}, {"a": "bread", "b": "BRED", "c": "noun", "d": "a baked food made from flour", "e": "I want bread and butter."}, {"a": "fruit", "b": "FROOT", "c": "noun", "d": "a sweet food like an apple or banana", "e": "Fruit is good for health."}, {"a": "hungry", "b": "HUNG-gree", "c": "adjective", "d": "wanting to eat", "e": "I am hungry."}, {"a": "thirsty", "b": "THUR-stee", "c": "adjective", "d": "wanting to drink", "e": "The child is thirsty."}], "tip": "The 'r' in 'rice' and 'bread' should be soft, not rolled.", "speaking": "Say: 'I am hungry. I want to eat ___.' Replace the blank with real food.", "quiz": [{"type": "mcq", "q": "What does \"water\" mean?", "options": ["a clear drink everyone needs", "a common food made of small white grains", "a baked food made from flour", "a sweet food like an apple or banana"], "answer": 0, "explanation": "\"water\" means a clear drink everyone needs."}, {"type": "mcq", "q": "What does \"rice\" mean?", "options": ["a common food made of small white grains", "a clear drink everyone needs", "a baked food made from flour", "a sweet food like an apple or banana"], "answer": 0, "explanation": "\"rice\" means a common food made of small white grains."}, {"type": "mcq", "q": "What does \"bread\" mean?", "options": ["a baked food made from flour", "a clear drink everyone needs", "a common food made of small white grains", "a sweet food like an apple or banana"], "answer": 0, "explanation": "\"bread\" means a baked food made from flour."}, {"type": "mcq", "q": "What does \"fruit\" mean?", "options": ["a sweet food like an apple or banana", "a clear drink everyone needs", "a common food made of small white grains", "a baked food made from flour"], "answer": 0, "explanation": "\"fruit\" means a sweet food like an apple or banana."}, {"type": "fill", "q": "I am ____.", "answer": "hungry", "explanation": "The word is \"hungry\" — wanting to eat."}, {"type": "fill", "q": "The child is ____.", "answer": "thirsty", "explanation": "The word is \"thirsty\" — wanting to drink."}]}, {"id": 7, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "Home & Objects", "focus": "Naming things around the house", "type": "vocab", "intro": "These words let you talk about your daily surroundings.", "items": [{"a": "house", "b": "HOWSS", "c": "noun", "d": "a building where people live", "e": "This is my house."}, {"a": "room", "b": "ROOM", "c": "noun", "d": "a part of a house with walls", "e": "My room is small."}, {"a": "door", "b": "DOR", "c": "noun", "d": "you open it to enter a room", "e": "Please close the door."}, {"a": "table", "b": "TAY-buul", "c": "noun", "d": "furniture you eat or write on", "e": "Put the book on the table."}, {"a": "chair", "b": "CHAIR", "c": "noun", "d": "furniture you sit on", "e": "Sit on the chair."}, {"a": "key", "b": "KEE", "c": "noun", "d": "a small metal object that opens locks", "e": "I lost my key."}], "tip": "Do not add an extra vowel sound at the end of 'table' — it ends softly, not 'tay-bul-uh'.", "speaking": "Walk around your home and name five objects in English.", "quiz": [{"type": "mcq", "q": "What does \"house\" mean?", "options": ["a building where people live", "a part of a house with walls", "you open it to enter a room", "furniture you eat or write on"], "answer": 0, "explanation": "\"house\" means a building where people live."}, {"type": "mcq", "q": "What does \"room\" mean?", "options": ["a part of a house with walls", "a building where people live", "you open it to enter a room", "furniture you eat or write on"], "answer": 0, "explanation": "\"room\" means a part of a house with walls."}, {"type": "mcq", "q": "What does \"door\" mean?", "options": ["you open it to enter a room", "a building where people live", "a part of a house with walls", "furniture you eat or write on"], "answer": 0, "explanation": "\"door\" means you open it to enter a room."}, {"type": "mcq", "q": "What does \"table\" mean?", "options": ["furniture you eat or write on", "a building where people live", "a part of a house with walls", "you open it to enter a room"], "answer": 0, "explanation": "\"table\" means furniture you eat or write on."}, {"type": "fill", "q": "Sit on the ____.", "answer": "chair", "explanation": "The word is \"chair\" — furniture you sit on."}, {"type": "fill", "q": "I lost my ____.", "answer": "key", "explanation": "The word is \"key\" — a small metal object that opens locks."}]}, {"id": 8, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "Clothes & Weather", "focus": "What you wear and what's outside", "type": "vocab", "intro": "Clothing and weather words come up in almost every daily conversation.", "items": [{"a": "shirt", "b": "SHURT", "c": "noun", "d": "clothing for your upper body", "e": "He is wearing a blue shirt."}, {"a": "shoes", "b": "SHOOZ", "c": "noun", "d": "clothing for your feet", "e": "My shoes are new."}, {"a": "rain", "b": "RAYN", "c": "noun", "d": "water that falls from the sky", "e": "It is raining outside."}, {"a": "sun", "b": "SUHN", "c": "noun", "d": "the bright star that gives us light", "e": "The sun is very hot today."}, {"a": "cold", "b": "KOHLD", "c": "adjective", "d": "having a low temperature", "e": "The water is cold."}, {"a": "hot", "b": "HOT", "c": "adjective", "d": "having a high temperature", "e": "The tea is hot."}], "tip": "Notice 'shirt' and 'shoes' both start with the 'sh' sound — round your lips slightly.", "speaking": "Describe today's weather and what you are wearing, in two sentences.", "quiz": [{"type": "mcq", "q": "What does \"shirt\" mean?", "options": ["clothing for your upper body", "clothing for your feet", "water that falls from the sky", "the bright star that gives us light"], "answer": 0, "explanation": "\"shirt\" means clothing for your upper body."}, {"type": "mcq", "q": "What does \"shoes\" mean?", "options": ["clothing for your feet", "clothing for your upper body", "water that falls from the sky", "the bright star that gives us light"], "answer": 0, "explanation": "\"shoes\" means clothing for your feet."}, {"type": "mcq", "q": "What does \"rain\" mean?", "options": ["water that falls from the sky", "clothing for your upper body", "clothing for your feet", "the bright star that gives us light"], "answer": 0, "explanation": "\"rain\" means water that falls from the sky."}, {"type": "mcq", "q": "What does \"sun\" mean?", "options": ["the bright star that gives us light", "clothing for your upper body", "clothing for your feet", "water that falls from the sky"], "answer": 0, "explanation": "\"sun\" means the bright star that gives us light."}, {"type": "fill", "q": "The water is ____.", "answer": "cold", "explanation": "The word is \"cold\" — having a low temperature."}, {"type": "fill", "q": "The tea is ____.", "answer": "hot", "explanation": "The word is \"hot\" — having a high temperature."}]}, {"id": 9, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "Animals & Nature", "focus": "The natural world around us", "type": "vocab", "intro": "Nature vocabulary is useful for storytelling and everyday description.", "items": [{"a": "dog", "b": "DAWG", "c": "noun", "d": "a common pet animal that barks", "e": "The dog is playing."}, {"a": "cat", "b": "KAT", "c": "noun", "d": "a common pet animal that says meow", "e": "My cat sleeps a lot."}, {"a": "bird", "b": "BURD", "c": "noun", "d": "an animal that can fly", "e": "A bird is singing."}, {"a": "tree", "b": "TREE", "c": "noun", "d": "a tall plant with a trunk", "e": "We sat under a tree."}, {"a": "river", "b": "RIV-er", "c": "noun", "d": "a large natural stream of water", "e": "The river is long."}, {"a": "sky", "b": "SKY", "c": "noun", "d": "the space above the earth", "e": "The sky is clear today."}], "tip": "Keep 'tree' crisp — the 't' and 'r' blend smoothly, no gap between them.", "speaking": "Describe a place in nature you like, using at least three of today's words.", "quiz": [{"type": "mcq", "q": "What does \"dog\" mean?", "options": ["a common pet animal that barks", "a common pet animal that says meow", "an animal that can fly", "a tall plant with a trunk"], "answer": 0, "explanation": "\"dog\" means a common pet animal that barks."}, {"type": "mcq", "q": "What does \"cat\" mean?", "options": ["a common pet animal that says meow", "a common pet animal that barks", "an animal that can fly", "a tall plant with a trunk"], "answer": 0, "explanation": "\"cat\" means a common pet animal that says meow."}, {"type": "mcq", "q": "What does \"bird\" mean?", "options": ["an animal that can fly", "a common pet animal that barks", "a common pet animal that says meow", "a tall plant with a trunk"], "answer": 0, "explanation": "\"bird\" means an animal that can fly."}, {"type": "mcq", "q": "What does \"tree\" mean?", "options": ["a tall plant with a trunk", "a common pet animal that barks", "a common pet animal that says meow", "an animal that can fly"], "answer": 0, "explanation": "\"tree\" means a tall plant with a trunk."}, {"type": "fill", "q": "The ____ is long.", "answer": "river", "explanation": "The word is \"river\" — a large natural stream of water."}, {"type": "fill", "q": "The ____ is clear today.", "answer": "sky", "explanation": "The word is \"sky\" — the space above the earth."}]}, {"id": 10, "stage": "Stage 1 · Foundation Words", "stageName": "Stage 1 · Foundation Words", "title": "Everyday Verbs", "focus": "Action words you use constantly", "type": "vocab", "intro": "Verbs bring your sentences to life. These six verbs alone can build hundreds of useful sentences.", "items": [{"a": "go", "b": "GOH", "c": "verb", "d": "to move from one place to another", "e": "I go to school every day."}, {"a": "eat", "b": "EET", "c": "verb", "d": "to put food in your mouth and swallow it", "e": "We eat dinner at 8pm."}, {"a": "sleep", "b": "SLEEP", "c": "verb", "d": "to rest with your eyes closed at night", "e": "I sleep for eight hours."}, {"a": "read", "b": "REED", "c": "verb", "d": "to look at words and understand them", "e": "She reads a book every night."}, {"a": "speak", "b": "SPEEK", "c": "verb", "d": "to say words out loud", "e": "I want to speak English well."}, {"a": "work", "b": "WURK", "c": "verb", "d": "to do a job or task", "e": "My father works in an office."}], "tip": "Say the sentence 'I want to speak English well' every day — it is your course motto.", "speaking": "Say five sentences about your daily routine using today's verbs: 'I go... I eat... I sleep...'", "quiz": [{"type": "mcq", "q": "What does \"go\" mean?", "options": ["to move from one place to another", "to put food in your mouth and swallow it", "to rest with your eyes closed at night", "to look at words and understand them"], "answer": 0, "explanation": "\"go\" means to move from one place to another."}, {"type": "mcq", "q": "What does \"eat\" mean?", "options": ["to put food in your mouth and swallow it", "to move from one place to another", "to rest with your eyes closed at night", "to look at words and understand them"], "answer": 0, "explanation": "\"eat\" means to put food in your mouth and swallow it."}, {"type": "mcq", "q": "What does \"sleep\" mean?", "options": ["to rest with your eyes closed at night", "to move from one place to another", "to put food in your mouth and swallow it", "to look at words and understand them"], "answer": 0, "explanation": "\"sleep\" means to rest with your eyes closed at night."}, {"type": "mcq", "q": "What does \"read\" mean?", "options": ["to look at words and understand them", "to move from one place to another", "to put food in your mouth and swallow it", "to rest with your eyes closed at night"], "answer": 0, "explanation": "\"read\" means to look at words and understand them."}, {"type": "fill", "q": "I want to ____ English well.", "answer": "speak", "explanation": "The word is \"speak\" — to say words out loud."}, {"type": "fill", "q": "My father ____s in an office.", "answer": "work", "explanation": "The word is \"work\" — to do a job or task."}]}, {"id": 11, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "Introducing Yourself", "focus": "Basic self-introduction", "type": "sentence", "intro": "Now that you know many words, let's put them together into full, useful sentences you will use in real life.", "items": [{"a": "Hi, my name is Anjali.", "b": "hy, my NAYM iz an-JAH-lee", "c": "Use this when you meet someone new."}, {"a": "I am from India.", "b": "eye AM frum IN-dee-uh", "c": "Use this to say where you are from."}, {"a": "Nice to meet you.", "b": "NYSS too MEET yoo", "c": "Say this right after someone introduces themselves."}, {"a": "How are you today?", "b": "how ar yoo tuh-DAY", "c": "A friendly question to start a conversation."}, {"a": "I am fine, thank you.", "b": "eye am FYN, thank yoo", "c": "A standard, polite reply to 'How are you?'"}, {"a": "What is your name?", "b": "wut iz yor NAYM", "c": "Use this to politely ask someone's name."}], "tip": "Let your voice rise slightly at the end of a question like 'How are you today?'", "speaking": "Introduce yourself out loud in four sentences, as if meeting a new person.", "quiz": [{"type": "fill", "q": "Hi, my name is ____.", "answer": "Anjali", "explanation": "Full sentence: \"Hi, my name is Anjali.\""}, {"type": "fill", "q": "I am from ____.", "answer": "India", "explanation": "Full sentence: \"I am from India.\""}, {"type": "fill", "q": "____ to meet you.", "answer": "Nice", "explanation": "Full sentence: \"Nice to meet you.\""}, {"type": "mcq", "q": "When would you say: \"How are you today?\"?", "options": ["A friendly question to start a conversation.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A friendly question to start a conversation."}, {"type": "mcq", "q": "When would you say: \"I am fine, thank you.\"?", "options": ["A standard, polite reply to 'How are you?'", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A standard, polite reply to 'How are you?'"}, {"type": "mcq", "q": "When would you say: \"What is your name?\"?", "options": ["Use this to politely ask someone's name.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this to politely ask someone's name."}]}, {"id": 12, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "Small Talk & Greetings", "focus": "Casual daily conversation", "type": "sentence", "intro": "Small talk is short, friendly conversation. Mastering it makes you sound natural and confident.", "items": [{"a": "Good morning! Did you sleep well?", "b": "good MOR-ning, did yoo SLEEP wel", "c": "A warm way to greet someone in the morning."}, {"a": "It's a beautiful day, isn't it?", "b": "its uh BYOO-tih-ful day, IZ-unt it", "c": "A common way to comment on the weather."}, {"a": "Long time no see!", "b": "long tym no SEE", "c": "Say this to someone you haven't seen for a while."}, {"a": "How was your weekend?", "b": "how wuz yor WEEK-end", "c": "A friendly question for Mondays."}, {"a": "Take care!", "b": "tayk KAIR", "c": "A warm way to say goodbye."}, {"a": "See you later!", "b": "see yoo LAY-ter", "c": "An informal way to say goodbye."}], "tip": "'Isn't it' is often said quickly as 'IZ-n-it' in natural speech — don't worry about saying every letter clearly.", "speaking": "Practise a 30-second small-talk conversation with an imaginary friend, out loud.", "quiz": [{"type": "fill", "q": "Good ____ Did you sleep well?", "answer": "morning!", "explanation": "Full sentence: \"Good morning! Did you sleep well?\""}, {"type": "fill", "q": "It's a ____ day, isn't it?", "answer": "beautiful", "explanation": "Full sentence: \"It's a beautiful day, isn't it?\""}, {"type": "fill", "q": "____ time no see!", "answer": "Long", "explanation": "Full sentence: \"Long time no see!\""}, {"type": "mcq", "q": "When would you say: \"How was your weekend?\"?", "options": ["A friendly question for Mondays.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A friendly question for Mondays."}, {"type": "mcq", "q": "When would you say: \"Take care!\"?", "options": ["A warm way to say goodbye.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A warm way to say goodbye."}, {"type": "mcq", "q": "When would you say: \"See you later!\"?", "options": ["An informal way to say goodbye.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "An informal way to say goodbye."}]}, {"id": 13, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "At the Shop", "focus": "Shopping conversations", "type": "sentence", "intro": "These sentences will help you shop confidently in English, from asking prices to paying.", "items": [{"a": "How much does this cost?", "b": "how MUCH duz this KOST", "c": "Use this to ask the price of an item."}, {"a": "Do you have this in a different size?", "b": "doo yoo hav this in uh DIF-er-unt SYZ", "c": "Use this when clothes shopping."}, {"a": "I would like to buy this, please.", "b": "eye wud LYK too BY this, pleez", "c": "A polite way to say you want to purchase something."}, {"a": "Can I pay by card?", "b": "kan eye PAY by KARD", "c": "Use this to ask about payment methods."}, {"a": "Do you have a discount?", "b": "doo yoo hav uh DIS-kownt", "c": "Use this to politely ask for a lower price."}, {"a": "Where is the billing counter?", "b": "wair iz thuh BIL-ing KOWN-ter", "c": "Use this to find where to pay."}], "tip": "Stress the important word in a question: 'How MUCH does this cost?'", "speaking": "Role-play a shopping scene: ask the price of three things and 'buy' one.", "quiz": [{"type": "fill", "q": "How ____ does this cost?", "answer": "much", "explanation": "Full sentence: \"How much does this cost?\""}, {"type": "fill", "q": "Do you have this in a ____ size?", "answer": "different", "explanation": "Full sentence: \"Do you have this in a different size?\""}, {"type": "fill", "q": "I would like to buy this, ____.", "answer": "please", "explanation": "Full sentence: \"I would like to buy this, please.\""}, {"type": "mcq", "q": "When would you say: \"Can I pay by card?\"?", "options": ["Use this to ask about payment methods.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this to ask about payment methods."}, {"type": "mcq", "q": "When would you say: \"Do you have a discount?\"?", "options": ["Use this to politely ask for a lower price.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this to politely ask for a lower price."}, {"type": "mcq", "q": "When would you say: \"Where is the billing counter?\"?", "options": ["Use this to find where to pay.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this to find where to pay."}]}, {"id": 14, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "Asking for Directions", "focus": "Finding your way", "type": "sentence", "intro": "Being able to ask for and understand directions is one of the most practical speaking skills.", "items": [{"a": "Excuse me, where is the nearest bus stop?", "b": "ek-SKYOOZ mee, wair iz thuh NEER-ist BUS stop", "c": "A polite way to start asking for directions."}, {"a": "How do I get to the railway station?", "b": "how doo eye GET too thuh RAYL-way STAY-shun", "c": "Use this to ask for a route."}, {"a": "Is it far from here?", "b": "iz it FAR frum heer", "c": "Use this to check the distance."}, {"a": "Turn left at the next corner.", "b": "turn LEFT at thuh nekst KOR-ner", "c": "A common instruction you might hear."}, {"a": "Go straight and it's on your right.", "b": "goh STRAYT and its on yor RYT", "c": "Another common direction instruction."}, {"a": "Thank you for your help.", "b": "thank yoo for yor HELP", "c": "Always thank someone who helps you."}], "tip": "'Excuse me' softens any request — say it gently, not too fast.", "speaking": "Ask an imaginary stranger for directions to your home, then reply with directions yourself.", "quiz": [{"type": "fill", "q": "Excuse me, where is the ____ bus stop?", "answer": "nearest", "explanation": "Full sentence: \"Excuse me, where is the nearest bus stop?\""}, {"type": "fill", "q": "How do I get to the ____ station?", "answer": "railway", "explanation": "Full sentence: \"How do I get to the railway station?\""}, {"type": "fill", "q": "Is it far ____ here?", "answer": "from", "explanation": "Full sentence: \"Is it far from here?\""}, {"type": "mcq", "q": "When would you say: \"Turn left at the next corner.\"?", "options": ["A common instruction you might hear.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A common instruction you might hear."}, {"type": "mcq", "q": "When would you say: \"Go straight and it's on your right.\"?", "options": ["Another common direction instruction.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Another common direction instruction."}, {"type": "mcq", "q": "When would you say: \"Thank you for your help.\"?", "options": ["Always thank someone who helps you.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Always thank someone who helps you."}]}, {"id": 15, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "At a Restaurant", "focus": "Ordering food and drink", "type": "sentence", "intro": "Restaurants are a great place to practise polite requests and questions.", "items": [{"a": "Can I see the menu, please?", "b": "kan eye SEE thuh MEN-yoo, pleez", "c": "Use this when you sit down at a restaurant."}, {"a": "I would like to order the chicken curry.", "b": "eye wud LYK too OR-der thuh CHIK-en KUR-ree", "c": "Use this to place your order."}, {"a": "Is this dish spicy?", "b": "iz this DISH SPY-see", "c": "Use this to check how spicy a dish is."}, {"a": "Could I have some water, please?", "b": "kud eye hav sum WAH-ter, pleez", "c": "A polite request during a meal."}, {"a": "The food was delicious, thank you.", "b": "thuh FOOD wuz duh-LISH-us, thank yoo", "c": "A nice compliment after eating."}, {"a": "Could we have the bill, please?", "b": "kud wee hav thuh BIL, pleez", "c": "Use this when you are ready to pay."}], "tip": "'Could I' and 'Could we' sound more polite than 'Can I' in formal settings.", "speaking": "Order a full imaginary three-course meal out loud, using today's sentences.", "quiz": [{"type": "fill", "q": "Can I see the menu, ____?", "answer": "please", "explanation": "Full sentence: \"Can I see the menu, please?\""}, {"type": "fill", "q": "I would like to order the ____ curry.", "answer": "chicken", "explanation": "Full sentence: \"I would like to order the chicken curry.\""}, {"type": "fill", "q": "Is this dish ____?", "answer": "spicy", "explanation": "Full sentence: \"Is this dish spicy?\""}, {"type": "mcq", "q": "When would you say: \"Could I have some water, please?\"?", "options": ["A polite request during a meal.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A polite request during a meal."}, {"type": "mcq", "q": "When would you say: \"The food was delicious, thank you.\"?", "options": ["A nice compliment after eating.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A nice compliment after eating."}, {"type": "mcq", "q": "When would you say: \"Could we have the bill, please?\"?", "options": ["Use this when you are ready to pay.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this when you are ready to pay."}]}, {"id": 16, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "On the Phone", "focus": "Telephone conversations", "type": "sentence", "intro": "Phone conversations can feel harder because you cannot see the other person — these phrases help.", "items": [{"a": "Hello, may I speak to Mr. Sharma, please?", "b": "heh-LOH, may eye SPEEK too MIS-ter SHAR-ma, pleez", "c": "A polite way to start a phone call."}, {"a": "This is Rahul speaking.", "b": "this iz ra-HOOL SPEEK-ing", "c": "A common way to identify yourself on the phone."}, {"a": "Could you repeat that, please?", "b": "kud yoo ri-PEET that, pleez", "c": "Use this if you didn't hear clearly."}, {"a": "Can you call me back later?", "b": "kan yoo KAWL mee BAK LAY-ter", "c": "Use this if you cannot talk right now."}, {"a": "I'll call you back in ten minutes.", "b": "eyel KAWL yoo bak in TEN MIN-its", "c": "A useful phrase for ending a call temporarily."}, {"a": "Thank you for calling, goodbye.", "b": "thank yoo for KAWL-ing, good-BY", "c": "A polite way to end a phone call."}], "tip": "Speak a little slower and clearer on the phone than in person — the listener cannot see your face.", "speaking": "Practise a full phone call: greeting, a question, and a polite goodbye.", "quiz": [{"type": "fill", "q": "Hello, may I speak to Mr. ____, please?", "answer": "Sharma", "explanation": "Full sentence: \"Hello, may I speak to Mr. Sharma, please?\""}, {"type": "fill", "q": "This is Rahul ____.", "answer": "speaking", "explanation": "Full sentence: \"This is Rahul speaking.\""}, {"type": "fill", "q": "Could you ____ that, please?", "answer": "repeat", "explanation": "Full sentence: \"Could you repeat that, please?\""}, {"type": "mcq", "q": "When would you say: \"Can you call me back later?\"?", "options": ["Use this if you cannot talk right now.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this if you cannot talk right now."}, {"type": "mcq", "q": "When would you say: \"I'll call you back in ten minutes.\"?", "options": ["A useful phrase for ending a call temporarily.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A useful phrase for ending a call temporarily."}, {"type": "mcq", "q": "When would you say: \"Thank you for calling, goodbye.\"?", "options": ["A polite way to end a phone call.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A polite way to end a phone call."}]}, {"id": 17, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "Making Plans", "focus": "Invitations and arrangements", "type": "sentence", "intro": "These sentences help you invite people and arrange to meet.", "items": [{"a": "Are you free this weekend?", "b": "ar yoo FREE this WEEK-end", "c": "Use this to check someone's availability."}, {"a": "Would you like to come to my house?", "b": "wud yoo LYK too kum too my HOWSS", "c": "A polite invitation."}, {"a": "Let's meet at six o'clock.", "b": "lets MEET at siks oh-KLOK", "c": "Use this to suggest a meeting time."}, {"a": "Sounds good, see you then.", "b": "sowndz GOOD, see yoo THEN", "c": "A common way to agree to plans."}, {"a": "I'm sorry, I can't make it.", "b": "eyem SOR-ee, eye KANT make it", "c": "A polite way to decline an invitation."}, {"a": "Can we reschedule for another day?", "b": "kan wee ree-SKED-yool for uh-NUH-ther DAY", "c": "Use this to change plans politely."}], "tip": "The contraction 'can't' is pronounced with a short vowel: 'KANT', not 'ka-ant'.", "speaking": "Invite someone to an event and agree on a time, speaking both parts yourself.", "quiz": [{"type": "fill", "q": "Are you free this ____?", "answer": "weekend", "explanation": "Full sentence: \"Are you free this weekend?\""}, {"type": "fill", "q": "____ you like to come to my house?", "answer": "Would", "explanation": "Full sentence: \"Would you like to come to my house?\""}, {"type": "fill", "q": "Let's meet at six ____.", "answer": "o'clock", "explanation": "Full sentence: \"Let's meet at six o'clock.\""}, {"type": "mcq", "q": "When would you say: \"Sounds good, see you then.\"?", "options": ["A common way to agree to plans.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A common way to agree to plans."}, {"type": "mcq", "q": "When would you say: \"I'm sorry, I can't make it.\"?", "options": ["A polite way to decline an invitation.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A polite way to decline an invitation."}, {"type": "mcq", "q": "When would you say: \"Can we reschedule for another day?\"?", "options": ["Use this to change plans politely.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this to change plans politely."}]}, {"id": 18, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "Weather & Feelings", "focus": "Describing how things feel", "type": "sentence", "intro": "Talking about weather and feelings is one of the most common daily conversation topics.", "items": [{"a": "It is very hot today.", "b": "it iz VER-ee HOT tuh-day", "c": "A simple weather comment."}, {"a": "I think it might rain later.", "b": "eye THINK it myt RAYN LAY-ter", "c": "A way to guess about future weather."}, {"a": "I feel a little tired today.", "b": "eye FEEL uh LIT-l TY-erd tuh-day", "c": "Use this to describe your energy level."}, {"a": "I am really happy about the news.", "b": "eye am REE-lee HAP-ee uh-bowt thuh NOOZ", "c": "A way to express happiness."}, {"a": "I'm feeling a bit nervous.", "b": "eyem FEEL-ing uh bit NUR-vus", "c": "Use this to express mild worry."}, {"a": "That makes me really excited!", "b": "that MAYKS mee REE-lee ek-SY-ted", "c": "A way to express enthusiasm."}], "tip": "Feelings words like 'excited' and 'nervous' carry strong stress on the middle syllable.", "speaking": "Describe today's weather and your current mood, in two full sentences.", "quiz": [{"type": "fill", "q": "It is very hot ____.", "answer": "today", "explanation": "Full sentence: \"It is very hot today.\""}, {"type": "fill", "q": "I ____ it might rain later.", "answer": "think", "explanation": "Full sentence: \"I think it might rain later.\""}, {"type": "fill", "q": "I feel a ____ tired today.", "answer": "little", "explanation": "Full sentence: \"I feel a little tired today.\""}, {"type": "mcq", "q": "When would you say: \"I am really happy about the news.\"?", "options": ["A way to express happiness.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A way to express happiness."}, {"type": "mcq", "q": "When would you say: \"I'm feeling a bit nervous.\"?", "options": ["Use this to express mild worry.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this to express mild worry."}, {"type": "mcq", "q": "When would you say: \"That makes me really excited!\"?", "options": ["A way to express enthusiasm.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A way to express enthusiasm."}]}, {"id": 19, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "At the Doctor", "focus": "Talking about health", "type": "sentence", "intro": "Health vocabulary is essential — you should be able to describe how you feel clearly.", "items": [{"a": "I am not feeling well.", "b": "eye am not FEEL-ing WEL", "c": "A general way to say you feel sick."}, {"a": "I have a headache.", "b": "eye hav uh HED-ayk", "c": "Use this to describe a specific pain."}, {"a": "I have had a fever since yesterday.", "b": "eye hav had uh FEE-ver sins YES-ter-day", "c": "Use this to describe how long you've been sick."}, {"a": "Could you recommend some medicine?", "b": "kud yoo rek-uh-MEND sum MED-i-sin", "c": "A polite request to a pharmacist or doctor."}, {"a": "How often should I take this?", "b": "how OF-en shud eye TAYK this", "c": "Use this to ask about medicine dosage."}, {"a": "I hope you feel better soon.", "b": "eye HOHP yoo feel BET-er SOON", "c": "A kind thing to say to someone who is sick."}], "tip": "Say 'headache' as one smooth word: HED-ayk, with stress on the first part.", "speaking": "Describe a health problem to an imaginary doctor and ask one follow-up question.", "quiz": [{"type": "fill", "q": "I am not ____ well.", "answer": "feeling", "explanation": "Full sentence: \"I am not feeling well.\""}, {"type": "fill", "q": "I have a ____.", "answer": "headache", "explanation": "Full sentence: \"I have a headache.\""}, {"type": "fill", "q": "I have had a fever since ____.", "answer": "yesterday", "explanation": "Full sentence: \"I have had a fever since yesterday.\""}, {"type": "mcq", "q": "When would you say: \"Could you recommend some medicine?\"?", "options": ["A polite request to a pharmacist or doctor.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A polite request to a pharmacist or doctor."}, {"type": "mcq", "q": "When would you say: \"How often should I take this?\"?", "options": ["Use this to ask about medicine dosage.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this to ask about medicine dosage."}, {"type": "mcq", "q": "When would you say: \"I hope you feel better soon.\"?", "options": ["A kind thing to say to someone who is sick.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A kind thing to say to someone who is sick."}]}, {"id": 20, "stage": "Stage 2 · Everyday Sentences", "stageName": "Stage 2 · Everyday Sentences", "title": "Travel & Airport Talk", "focus": "Getting around while travelling", "type": "sentence", "intro": "This level completes your everyday-sentence toolkit with useful travel English.", "items": [{"a": "Where is the check-in counter?", "b": "wair iz thuh CHEK-in KOWN-ter", "c": "Use this at the airport."}, {"a": "I would like a window seat, please.", "b": "eye wud LYK uh WIN-doh SEET, pleez", "c": "A common request when checking in for a flight."}, {"a": "What time does the flight depart?", "b": "wut TYM duz thuh FLYT dee-PART", "c": "Use this to check departure time."}, {"a": "Is this seat taken?", "b": "iz this SEET TAY-ken", "c": "Use this to politely ask about an empty seat."}, {"a": "Could you help me with my luggage?", "b": "kud yoo HELP mee with my LUG-ij", "c": "A polite request for assistance."}, {"a": "Have a safe journey!", "b": "hav uh SAYF JUR-nee", "c": "A kind farewell for a traveller."}], "tip": "Travel words like 'luggage' and 'journey' both stress the first syllable.", "speaking": "Narrate a short imaginary journey from home to the airport, using today's sentences.", "quiz": [{"type": "fill", "q": "Where is the ____ counter?", "answer": "check-in", "explanation": "Full sentence: \"Where is the check-in counter?\""}, {"type": "fill", "q": "I would like a ____ seat, please.", "answer": "window", "explanation": "Full sentence: \"I would like a window seat, please.\""}, {"type": "fill", "q": "What time does the ____ depart?", "answer": "flight", "explanation": "Full sentence: \"What time does the flight depart?\""}, {"type": "mcq", "q": "When would you say: \"Is this seat taken?\"?", "options": ["Use this to politely ask about an empty seat.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "Use this to politely ask about an empty seat."}, {"type": "mcq", "q": "When would you say: \"Could you help me with my luggage?\"?", "options": ["A polite request for assistance.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A polite request for assistance."}, {"type": "mcq", "q": "When would you say: \"Have a safe journey!\"?", "options": ["A kind farewell for a traveller.", "Used to end a conversation politely.", "Used only in formal writing.", "Used when you are angry."], "answer": 0, "explanation": "A kind farewell for a traveller."}]}, {"id": 21, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Present Simple", "focus": "Talking about habits and facts", "type": "grammar", "intro": "Grammar is the skeleton of fluent speech. The Present Simple describes routines, habits, and facts that are always true.", "rule": "Structure: Subject + base verb (add -s for he/she/it). Example: I work. She works.", "items": [{"a": "I drink tea every morning.", "c": "Habit: describes a repeated action."}, {"a": "She works at a hospital.", "c": "Fact: add -s to the verb with he/she/it."}, {"a": "They live in Mumbai.", "c": "Fact: a permanent situation."}, {"a": "The sun rises in the east.", "c": "General truth: always true, no matter the time."}, {"a": "Do you speak English?", "c": "Question form: use 'Do/Does' + base verb."}, {"a": "He does not like coffee.", "c": "Negative form: use 'does not' + base verb for he/she/it."}], "tip": "In fast speech, 'does not' is usually shortened to 'doesn't' — practise saying it smoothly.", "speaking": "Say five true sentences about your daily routine using the Present Simple.", "quiz": [{"type": "fill", "q": "I drink tea every ____.", "answer": "morning", "explanation": "Habit: describes a repeated action."}, {"type": "fill", "q": "She works at a ____.", "answer": "hospital", "explanation": "Fact: add -s to the verb with he/she/it."}, {"type": "fill", "q": "They live in ____.", "answer": "Mumbai", "explanation": "Fact: a permanent situation."}, {"type": "fill", "q": "The sun rises in the ____.", "answer": "east", "explanation": "General truth: always true, no matter the time."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["Do you speak English?", "Do  you speak English? (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Question form: use 'Do/Does' + base verb."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["He does not like coffee.", "He  does not like coffee. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Negative form: use 'does not' + base verb for he/she/it."}]}, {"id": 22, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Present Continuous", "focus": "Talking about actions happening now", "type": "grammar", "intro": "Use the Present Continuous for actions happening right now, or temporary situations.", "rule": "Structure: Subject + am/is/are + verb-ing. Example: I am eating. They are talking.", "items": [{"a": "I am reading a book right now.", "c": "Describes an action happening at this moment."}, {"a": "She is cooking dinner.", "c": "Use 'is' with she/he/it."}, {"a": "We are learning English together.", "c": "Use 'are' with we/you/they."}, {"a": "It is raining outside.", "c": "Common use for describing current weather."}, {"a": "Are you listening to me?", "c": "Question form: Am/Is/Are + subject + verb-ing."}, {"a": "He is not working today.", "c": "Negative form: is/am/are + not + verb-ing."}], "tip": "The '-ing' ending is often shortened in casual speech to sound like '-in' — but write it fully.", "speaking": "Look around you and say three things that are happening right now.", "quiz": [{"type": "fill", "q": "I am reading a book right ____.", "answer": "now", "explanation": "Describes an action happening at this moment."}, {"type": "fill", "q": "She is cooking ____.", "answer": "dinner", "explanation": "Use 'is' with she/he/it."}, {"type": "fill", "q": "We are learning English ____.", "answer": "together", "explanation": "Use 'are' with we/you/they."}, {"type": "fill", "q": "It is raining ____.", "answer": "outside", "explanation": "Common use for describing current weather."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["Are you listening to me?", "Are  you listening to me? (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Question form: Am/Is/Are + subject + verb-ing."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["He is not working today.", "He  is not working today. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Negative form: is/am/are + not + verb-ing."}]}, {"id": 23, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Past Simple", "focus": "Talking about finished actions", "type": "grammar", "intro": "The Past Simple describes actions that started and finished in the past.", "rule": "Structure: Subject + past verb form (regular verbs add -ed). Example: I walked. She finished.", "items": [{"a": "I visited my grandmother last week.", "c": "Regular verb: add -ed to the base form."}, {"a": "She went to the market yesterday.", "c": "Irregular verb: 'go' becomes 'went'."}, {"a": "They watched a movie last night.", "c": "Regular verb with -ed ending."}, {"a": "We did not go to the party.", "c": "Negative form: did not + base verb."}, {"a": "Did you finish your homework?", "c": "Question form: Did + subject + base verb."}, {"a": "He arrived late for the meeting.", "c": "Regular verb describing a completed event."}], "tip": "The '-ed' ending has three sounds: /t/, /d/, or /id/ — 'watched' sounds like 'watcht'.", "speaking": "Tell a short story about your yesterday using five Past Simple sentences.", "quiz": [{"type": "fill", "q": "I visited my grandmother last ____.", "answer": "week", "explanation": "Regular verb: add -ed to the base form."}, {"type": "fill", "q": "She went to the market ____.", "answer": "yesterday", "explanation": "Irregular verb: 'go' becomes 'went'."}, {"type": "fill", "q": "They watched a movie last ____.", "answer": "night", "explanation": "Regular verb with -ed ending."}, {"type": "fill", "q": "We did not go to the ____.", "answer": "party", "explanation": "Negative form: did not + base verb."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["Did you finish your homework?", "Did  you finish your homework? (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Question form: Did + subject + base verb."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["He arrived late for the meeting.", "He  arrived late for the meeting. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Regular verb describing a completed event."}]}, {"id": 24, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Past Continuous", "focus": "Actions in progress in the past", "type": "grammar", "intro": "The Past Continuous describes an action that was in progress at a specific past moment, often interrupted by another action.", "rule": "Structure: Subject + was/were + verb-ing. Example: I was sleeping when you called.", "items": [{"a": "I was sleeping when the phone rang.", "c": "One action interrupts another in progress."}, {"a": "They were playing football at 5pm.", "c": "Describes an ongoing action at a specific time."}, {"a": "She was cooking while I was cleaning.", "c": "Two actions happening at the same time."}, {"a": "We were not watching TV last night.", "c": "Negative form: was/were + not + verb-ing."}, {"a": "What were you doing yesterday evening?", "c": "Question form: What + were/was + subject + verb-ing."}, {"a": "It was raining heavily during the match.", "c": "Describes background action while something else happened."}], "tip": "Link 'was' smoothly into the next word: 'was sleeping' sounds like 'wuz-SLEE-ping'.", "speaking": "Describe what you were doing at three different times yesterday.", "quiz": [{"type": "fill", "q": "I was sleeping when the phone ____.", "answer": "rang", "explanation": "One action interrupts another in progress."}, {"type": "fill", "q": "They were playing football at ____.", "answer": "5pm", "explanation": "Describes an ongoing action at a specific time."}, {"type": "fill", "q": "She was cooking while I was ____.", "answer": "cleaning", "explanation": "Two actions happening at the same time."}, {"type": "fill", "q": "We were not watching TV last ____.", "answer": "night", "explanation": "Negative form: was/were + not + verb-ing."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["What were you doing yesterday evening?", "What  were you doing yesterday evening? (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Question form: What + were/was + subject + verb-ing."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["It was raining heavily during the match.", "It  was raining heavily during the match. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Describes background action while something else happened."}]}, {"id": 25, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Future Forms", "focus": "Talking about tomorrow", "type": "grammar", "intro": "English has two common ways to talk about the future: 'will' for decisions and predictions, and 'going to' for plans.", "rule": "Structure: Subject + will + base verb, OR Subject + am/is/are + going to + base verb.", "items": [{"a": "I will call you tomorrow.", "c": "'Will' for a decision made now."}, {"a": "It is going to rain soon.", "c": "'Going to' for a prediction based on evidence."}, {"a": "We are going to visit our uncle next month.", "c": "'Going to' for a planned future event."}, {"a": "I think she will pass the exam.", "c": "'Will' for a prediction or opinion."}, {"a": "Will you help me with this?", "c": "Question form using 'will'."}, {"a": "They are not going to attend the wedding.", "c": "Negative form of 'going to'."}], "tip": "'Going to' is often pronounced quickly as 'gonna' in casual speech — but write it fully in exams.", "speaking": "Describe three real plans you have for next week using 'going to'.", "quiz": [{"type": "fill", "q": "I will call you ____.", "answer": "tomorrow", "explanation": "'Will' for a decision made now."}, {"type": "fill", "q": "It is going to rain ____.", "answer": "soon", "explanation": "'Going to' for a prediction based on evidence."}, {"type": "fill", "q": "We are going to visit our uncle next ____.", "answer": "month", "explanation": "'Going to' for a planned future event."}, {"type": "fill", "q": "I think she will pass the ____.", "answer": "exam", "explanation": "'Will' for a prediction or opinion."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["Will you help me with this?", "Will  you help me with this? (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Question form using 'will'."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["They are not going to attend the wedding.", "They  are not going to attend the wedding. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Negative form of 'going to'."}]}, {"id": 26, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Present Perfect", "focus": "Connecting past and present", "type": "grammar", "intro": "The Present Perfect connects a past action to the present moment — used for experiences and recent events.", "rule": "Structure: Subject + have/has + past participle. Example: I have finished. She has arrived.", "items": [{"a": "I have finished my homework.", "c": "Recent completed action relevant now."}, {"a": "She has visited Paris three times.", "c": "Life experience: use has with she/he/it."}, {"a": "We have already eaten dinner.", "c": "Completed action with 'already'."}, {"a": "Have you ever tried sushi?", "c": "Question about life experience."}, {"a": "They have not arrived yet.", "c": "Negative form with 'yet' for something expected."}, {"a": "He has just left the office.", "c": "Very recent action with 'just'."}], "tip": "'Have' often reduces to 've' in speech: 'I've finished' sounds like one smooth word.", "speaking": "Share three real experiences from your life using 'I have...'", "quiz": [{"type": "fill", "q": "I have finished my ____.", "answer": "homework", "explanation": "Recent completed action relevant now."}, {"type": "fill", "q": "She has visited Paris three ____.", "answer": "times", "explanation": "Life experience: use has with she/he/it."}, {"type": "fill", "q": "We have already eaten ____.", "answer": "dinner", "explanation": "Completed action with 'already'."}, {"type": "fill", "q": "Have you ever tried ____?", "answer": "sushi", "explanation": "Question about life experience."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["They have not arrived yet.", "They  have not arrived yet. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Negative form with 'yet' for something expected."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["He has just left the office.", "He  has just left the office. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Very recent action with 'just'."}]}, {"id": 27, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Modal Verbs", "focus": "Ability, permission, and advice", "type": "grammar", "intro": "Modal verbs like can, should, and must add meaning about ability, advice, permission, and necessity.", "rule": "Structure: Subject + modal + base verb (no -s, no 'to'). Example: She can swim. You should rest.", "items": [{"a": "I can speak two languages.", "c": "'Can' expresses ability."}, {"a": "You should drink more water.", "c": "'Should' gives advice."}, {"a": "We must finish this by Friday.", "c": "'Must' expresses strong necessity."}, {"a": "May I ask you a question?", "c": "'May' is used for polite permission."}, {"a": "You must not smoke here.", "c": "'Must not' expresses prohibition."}, {"a": "Could you pass the salt, please?", "c": "'Could' is used for polite requests."}], "tip": "Modal verbs are never followed by 'to' — say 'can speak', never 'can to speak'.", "speaking": "Give three pieces of advice to a friend using 'should' and 'must'.", "quiz": [{"type": "fill", "q": "I can speak two ____.", "answer": "languages", "explanation": "'Can' expresses ability."}, {"type": "fill", "q": "You should drink more ____.", "answer": "water", "explanation": "'Should' gives advice."}, {"type": "fill", "q": "We must finish this by ____.", "answer": "Friday", "explanation": "'Must' expresses strong necessity."}, {"type": "fill", "q": "May I ask you a ____?", "answer": "question", "explanation": "'May' is used for polite permission."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["You must not smoke here.", "You  must not smoke here. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "'Must not' expresses prohibition."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["Could you pass the salt, please?", "Could  you pass the salt, please? (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "'Could' is used for polite requests."}]}, {"id": 28, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Comparatives & Superlatives", "focus": "Comparing people and things", "type": "grammar", "intro": "Comparatives compare two things; superlatives describe the extreme within a group.", "rule": "Structure: adjective + -er + than (comparative); the + adjective + -est (superlative). Longer adjectives use 'more' and 'most'.", "items": [{"a": "This bag is bigger than that one.", "c": "Comparative: short adjective + -er + than."}, {"a": "She is the tallest student in the class.", "c": "Superlative: the + adjective + -est."}, {"a": "This book is more interesting than the last one.", "c": "Long adjectives use 'more' instead of -er."}, {"a": "He is the most intelligent person I know.", "c": "Long adjectives use 'the most' for superlatives."}, {"a": "My house is smaller than yours.", "c": "Comparative with a short adjective."}, {"a": "Today is the hottest day of the year.", "c": "Superlative describing an extreme."}], "tip": "Double the final consonant before -er/-est in short words: 'big' becomes 'bigger', not 'biger'.", "speaking": "Compare three things around you — for example, two chairs or two rooms.", "quiz": [{"type": "fill", "q": "This bag is bigger than that ____.", "answer": "one", "explanation": "Comparative: short adjective + -er + than."}, {"type": "fill", "q": "She is the tallest student in the ____.", "answer": "class", "explanation": "Superlative: the + adjective + -est."}, {"type": "fill", "q": "This book is more interesting than the last ____.", "answer": "one", "explanation": "Long adjectives use 'more' instead of -er."}, {"type": "fill", "q": "He is the most intelligent person I ____.", "answer": "know", "explanation": "Long adjectives use 'the most' for superlatives."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["My house is smaller than yours.", "My  house is smaller than yours. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Comparative with a short adjective."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["Today is the hottest day of the year.", "Today  is the hottest day of the year. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Superlative describing an extreme."}]}, {"id": 29, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Question Formation", "focus": "Asking clear questions", "type": "grammar", "intro": "Being able to ask questions confidently is essential for real conversation, not just answering.", "rule": "Structure: Question word (what/where/why/how) + auxiliary verb + subject + main verb.", "items": [{"a": "What time do you usually wake up?", "c": "'What time' asks about a specific time."}, {"a": "Where do you live?", "c": "'Where' asks about location."}, {"a": "Why are you learning English?", "c": "'Why' asks for a reason."}, {"a": "How do you make this dish?", "c": "'How' asks about a method."}, {"a": "Who is your best friend?", "c": "'Who' asks about a person."}, {"a": "How long have you been studying English?", "c": "'How long' asks about duration, often with Present Perfect."}], "tip": "Your voice should rise slightly at the end of yes/no questions, but fall at the end of 'wh-' questions.", "speaking": "Ask a partner (real or imaginary) five different questions using today's question words.", "quiz": [{"type": "fill", "q": "What time do you usually ____ up?", "answer": "wake", "explanation": "'What time' asks about a specific time."}, {"type": "fill", "q": "Where do you ____?", "answer": "live", "explanation": "'Where' asks about location."}, {"type": "fill", "q": "Why are you learning ____?", "answer": "English", "explanation": "'Why' asks for a reason."}, {"type": "fill", "q": "How do you make this ____?", "answer": "dish", "explanation": "'How' asks about a method."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["Who is your best friend?", "Who  is your best friend? (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "'Who' asks about a person."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["How long have you been studying English?", "How  long have you been studying English? (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "'How long' asks about duration, often with Present Perfect."}]}, {"id": 30, "stage": "Stage 3 · Grammar Foundations", "stageName": "Stage 3 · Grammar Foundations", "title": "Conditionals (If Clauses)", "focus": "Talking about possibilities", "type": "grammar", "intro": "Conditionals let you talk about real and imaginary situations — a key skill for sounding advanced.", "rule": "Structure (real/future): If + present simple, ... will + base verb. Structure (imaginary): If + past simple, ... would + base verb.", "items": [{"a": "If it rains, I will stay at home.", "c": "First conditional: a real, likely future situation."}, {"a": "If you study hard, you will pass the exam.", "c": "First conditional: cause and likely effect."}, {"a": "If I had more time, I would travel the world.", "c": "Second conditional: an imaginary, unlikely situation."}, {"a": "If I were you, I would apologize.", "c": "Second conditional: giving imaginative advice, using 'were' for all subjects."}, {"a": "If we leave now, we will not miss the train.", "c": "First conditional with a negative result."}, {"a": "What would you do if you won the lottery?", "c": "Second conditional question about an imaginary situation."}], "tip": "In the second conditional, native speakers always say 'if I were', not 'if I was', in careful speech.", "speaking": "Complete this out loud three times with different endings: 'If I had one wish, I would ___.'", "quiz": [{"type": "fill", "q": "If it rains, I will stay at ____.", "answer": "home", "explanation": "First conditional: a real, likely future situation."}, {"type": "fill", "q": "If you study hard, you will pass the ____.", "answer": "exam", "explanation": "First conditional: cause and likely effect."}, {"type": "fill", "q": "If I had more time, I would travel the ____.", "answer": "world", "explanation": "Second conditional: an imaginary, unlikely situation."}, {"type": "fill", "q": "If I were you, I would ____.", "answer": "apologize", "explanation": "Second conditional: giving imaginative advice, using 'were' for all subjects."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["If we leave now, we will not miss the train.", "If  we leave now, we will not miss the train. (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "First conditional with a negative result."}, {"type": "mcq", "q": "Which sentence is correct?", "options": ["What would you do if you won the lottery?", "What  would you do if you won the lottery? (wrong word order)", "This sentence have error.", "Not applicable"], "answer": 0, "explanation": "Second conditional question about an imaginary situation."}]}, {"id": 31, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Work & Office Vocabulary", "focus": "Talking about your job", "type": "vocab", "intro": "This vocabulary helps you discuss work, meetings, and colleagues confidently.", "items": [{"a": "colleague", "b": "KOL-eeg", "c": "noun", "d": "a person you work with", "e": "My colleague helped me with the report."}, {"a": "deadline", "b": "DED-lyn", "c": "noun", "d": "the latest time something must be finished", "e": "The deadline for this project is Friday."}, {"a": "meeting", "b": "MEE-ting", "c": "noun", "d": "a gathering to discuss something", "e": "We have a meeting at 10am."}, {"a": "manager", "b": "MAN-uh-jer", "c": "noun", "d": "a person who leads a team", "e": "My manager reviewed my work."}, {"a": "salary", "b": "SAL-uh-ree", "c": "noun", "d": "the money you earn from your job", "e": "She negotiated a higher salary."}, {"a": "promotion", "b": "pruh-MOH-shun", "c": "noun", "d": "a move to a higher position at work", "e": "He got a promotion last month."}], "tip": "Stress the second syllable in 'promotion': pruh-MOH-shun.", "speaking": "Describe your job (real or imagined) using three of today's words.", "quiz": [{"type": "mcq", "q": "What does \"colleague\" mean?", "options": ["a person you work with", "the latest time something must be finished", "a gathering to discuss something", "a person who leads a team"], "answer": 0, "explanation": "\"colleague\" means a person you work with."}, {"type": "mcq", "q": "What does \"deadline\" mean?", "options": ["the latest time something must be finished", "a person you work with", "a gathering to discuss something", "a person who leads a team"], "answer": 0, "explanation": "\"deadline\" means the latest time something must be finished."}, {"type": "mcq", "q": "What does \"meeting\" mean?", "options": ["a gathering to discuss something", "a person you work with", "the latest time something must be finished", "a person who leads a team"], "answer": 0, "explanation": "\"meeting\" means a gathering to discuss something."}, {"type": "mcq", "q": "What does \"manager\" mean?", "options": ["a person who leads a team", "a person you work with", "the latest time something must be finished", "a gathering to discuss something"], "answer": 0, "explanation": "\"manager\" means a person who leads a team."}, {"type": "fill", "q": "She negotiated a higher ____.", "answer": "salary", "explanation": "The word is \"salary\" — the money you earn from your job."}, {"type": "fill", "q": "He got a ____ last month.", "answer": "promotion", "explanation": "The word is \"promotion\" — a move to a higher position at work."}]}, {"id": 32, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Phrasal Verbs I", "focus": "Common two-word verbs", "type": "vocab", "intro": "Phrasal verbs are everywhere in natural English. Learning them makes you sound far more fluent.", "items": [{"a": "get up", "b": "get UP", "c": "phrasal verb", "d": "to rise from bed", "e": "I get up at 6am every day."}, {"a": "look for", "b": "look FOR", "c": "phrasal verb", "d": "to search for something", "e": "I am looking for my keys."}, {"a": "give up", "b": "giv UP", "c": "phrasal verb", "d": "to stop trying", "e": "Never give up on your goals."}, {"a": "turn off", "b": "turn OFF", "c": "phrasal verb", "d": "to stop a machine or light", "e": "Please turn off the lights."}, {"a": "find out", "b": "fynd OWT", "c": "phrasal verb", "d": "to discover information", "e": "I need to find out the answer."}, {"a": "fill out", "b": "fil OWT", "c": "phrasal verb", "d": "to complete a form", "e": "Please fill out this form."}], "tip": "The second word in a phrasal verb usually carries more stress: get UP, look FOR.", "speaking": "Use three phrasal verbs to describe your morning routine.", "quiz": [{"type": "mcq", "q": "What does \"get up\" mean?", "options": ["to rise from bed", "to search for something", "to stop trying", "to stop a machine or light"], "answer": 0, "explanation": "\"get up\" means to rise from bed."}, {"type": "mcq", "q": "What does \"look for\" mean?", "options": ["to search for something", "to rise from bed", "to stop trying", "to stop a machine or light"], "answer": 0, "explanation": "\"look for\" means to search for something."}, {"type": "mcq", "q": "What does \"give up\" mean?", "options": ["to stop trying", "to rise from bed", "to search for something", "to stop a machine or light"], "answer": 0, "explanation": "\"give up\" means to stop trying."}, {"type": "mcq", "q": "What does \"turn off\" mean?", "options": ["to stop a machine or light", "to rise from bed", "to search for something", "to stop trying"], "answer": 0, "explanation": "\"turn off\" means to stop a machine or light."}, {"type": "fill", "q": "I need to ____ the answer.", "answer": "find out", "explanation": "The word is \"find out\" — to discover information."}, {"type": "fill", "q": "Please ____ this form.", "answer": "fill out", "explanation": "The word is \"fill out\" — to complete a form."}]}, {"id": 33, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Prepositions of Place & Time", "focus": "Small words, big importance", "type": "vocab", "intro": "Prepositions are small but they change meaning completely — mastering them makes your speech precise.", "items": [{"a": "in", "b": "IN", "c": "preposition", "d": "inside a place, or within a time period", "e": "I live in Delhi. I was born in 1998."}, {"a": "on", "b": "ON", "c": "preposition", "d": "touching a surface, or a specific day", "e": "The book is on the table. See you on Monday."}, {"a": "at", "b": "AT", "c": "preposition", "d": "a specific point in place or time", "e": "I am at home. The class starts at 5pm."}, {"a": "between", "b": "bee-TWEEN", "c": "preposition", "d": "in the middle of two things", "e": "The shop is between the bank and the school."}, {"a": "during", "b": "DYOOR-ing", "c": "preposition", "d": "throughout a period of time", "e": "I felt sleepy during the meeting."}, {"a": "since", "b": "SINS", "c": "preposition", "d": "from a point in the past until now", "e": "I have lived here since 2015."}], "tip": "Use 'in' for months/years, 'on' for days/dates, 'at' for exact times — this small rule fixes many common mistakes.", "speaking": "Make one sentence with 'in', one with 'on', and one with 'at' about your own life.", "quiz": [{"type": "mcq", "q": "What does \"in\" mean?", "options": ["inside a place, or within a time period", "touching a surface, or a specific day", "a specific point in place or time", "in the middle of two things"], "answer": 0, "explanation": "\"in\" means inside a place, or within a time period."}, {"type": "mcq", "q": "What does \"on\" mean?", "options": ["touching a surface, or a specific day", "inside a place, or within a time period", "a specific point in place or time", "in the middle of two things"], "answer": 0, "explanation": "\"on\" means touching a surface, or a specific day."}, {"type": "mcq", "q": "What does \"at\" mean?", "options": ["a specific point in place or time", "inside a place, or within a time period", "touching a surface, or a specific day", "in the middle of two things"], "answer": 0, "explanation": "\"at\" means a specific point in place or time."}, {"type": "mcq", "q": "What does \"between\" mean?", "options": ["in the middle of two things", "inside a place, or within a time period", "touching a surface, or a specific day", "a specific point in place or time"], "answer": 0, "explanation": "\"between\" means in the middle of two things."}, {"type": "fill", "q": "I felt sleepy ____ the meeting.", "answer": "during", "explanation": "The word is \"during\" — throughout a period of time."}, {"type": "fill", "q": "I have lived here ____ 2015.", "answer": "since", "explanation": "The word is \"since\" — from a point in the past until now."}]}, {"id": 34, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Connecting Words", "focus": "Linking ideas smoothly", "type": "vocab", "intro": "Connectors join your ideas together, making longer, more sophisticated sentences.", "items": [{"a": "because", "b": "bee-KUZ", "c": "conjunction", "d": "gives a reason", "e": "I stayed home because I was sick."}, {"a": "although", "b": "awl-THOH", "c": "conjunction", "d": "shows contrast, similar to 'but'", "e": "Although it was raining, we went out."}, {"a": "however", "b": "how-EV-er", "c": "adverb", "d": "introduces a contrasting idea in a new sentence", "e": "I like tea. However, I prefer coffee in the morning."}, {"a": "so", "b": "SOH", "c": "conjunction", "d": "shows a result", "e": "It was late, so I went home."}, {"a": "also", "b": "AWL-soh", "c": "adverb", "d": "adds an extra point", "e": "She is smart. She is also very kind."}, {"a": "therefore", "b": "THAIR-for", "c": "adverb", "d": "shows a logical result, more formal than 'so'", "e": "The store was closed; therefore, we shopped online."}], "tip": "'However' is usually followed by a comma when it starts a sentence.", "speaking": "Combine two of your own simple sentences using 'because' and then 'although'.", "quiz": [{"type": "mcq", "q": "What does \"because\" mean?", "options": ["gives a reason", "shows contrast, similar to 'but'", "introduces a contrasting idea in a new sentence", "shows a result"], "answer": 0, "explanation": "\"because\" means gives a reason."}, {"type": "mcq", "q": "What does \"although\" mean?", "options": ["shows contrast, similar to 'but'", "gives a reason", "introduces a contrasting idea in a new sentence", "shows a result"], "answer": 0, "explanation": "\"although\" means shows contrast, similar to 'but'."}, {"type": "mcq", "q": "What does \"however\" mean?", "options": ["introduces a contrasting idea in a new sentence", "gives a reason", "shows contrast, similar to 'but'", "shows a result"], "answer": 0, "explanation": "\"however\" means introduces a contrasting idea in a new sentence."}, {"type": "mcq", "q": "What does \"so\" mean?", "options": ["shows a result", "gives a reason", "shows contrast, similar to 'but'", "introduces a contrasting idea in a new sentence"], "answer": 0, "explanation": "\"so\" means shows a result."}, {"type": "fill", "q": "She is smart. She is ____ very kind.", "answer": "also", "explanation": "The word is \"also\" — adds an extra point."}, {"type": "fill", "q": "The store was closed; ____, we shopped online.", "answer": "therefore", "explanation": "The word is \"therefore\" — shows a logical result, more formal than 'so'."}]}, {"id": 35, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Emotions Vocabulary", "focus": "Describing feelings precisely", "type": "vocab", "intro": "Precise emotion words help people understand exactly how you feel, beyond just 'good' or 'bad'.", "items": [{"a": "delighted", "b": "dee-LY-ted", "c": "adjective", "d": "very pleased and happy", "e": "I was delighted to see my old friend."}, {"a": "frustrated", "b": "frus-TRAY-ted", "c": "adjective", "d": "annoyed because something isn't working", "e": "I felt frustrated when the internet stopped."}, {"a": "anxious", "b": "ANK-shus", "c": "adjective", "d": "worried or nervous about something", "e": "She felt anxious before the interview."}, {"a": "relieved", "b": "ree-LEEVD", "c": "adjective", "d": "no longer worried after stress ends", "e": "I was relieved when the exam was over."}, {"a": "confident", "b": "KON-fi-dent", "c": "adjective", "d": "sure of your own abilities", "e": "He felt confident before the presentation."}, {"a": "grateful", "b": "GRAYT-ful", "c": "adjective", "d": "thankful for something", "e": "I am grateful for your support."}], "tip": "Say 'confident' with stress on the first syllable: KON-fi-dent.", "speaking": "Describe a real memory using two emotion words from today's list.", "quiz": [{"type": "mcq", "q": "What does \"delighted\" mean?", "options": ["very pleased and happy", "annoyed because something isn't working", "worried or nervous about something", "no longer worried after stress ends"], "answer": 0, "explanation": "\"delighted\" means very pleased and happy."}, {"type": "mcq", "q": "What does \"frustrated\" mean?", "options": ["annoyed because something isn't working", "very pleased and happy", "worried or nervous about something", "no longer worried after stress ends"], "answer": 0, "explanation": "\"frustrated\" means annoyed because something isn't working."}, {"type": "mcq", "q": "What does \"anxious\" mean?", "options": ["worried or nervous about something", "very pleased and happy", "annoyed because something isn't working", "no longer worried after stress ends"], "answer": 0, "explanation": "\"anxious\" means worried or nervous about something."}, {"type": "mcq", "q": "What does \"relieved\" mean?", "options": ["no longer worried after stress ends", "very pleased and happy", "annoyed because something isn't working", "worried or nervous about something"], "answer": 0, "explanation": "\"relieved\" means no longer worried after stress ends."}, {"type": "fill", "q": "He felt ____ before the presentation.", "answer": "confident", "explanation": "The word is \"confident\" — sure of your own abilities."}, {"type": "fill", "q": "I am ____ for your support.", "answer": "grateful", "explanation": "The word is \"grateful\" — thankful for something."}]}, {"id": 36, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Money & Shopping Vocabulary", "focus": "Talking about spending and saving", "type": "vocab", "intro": "This vocabulary goes beyond basic shopping into budgeting and finance conversations.", "items": [{"a": "budget", "b": "BUH-jet", "c": "noun", "d": "a plan for how to spend money", "e": "I need to stick to my budget this month."}, {"a": "expensive", "b": "ek-SPEN-siv", "c": "adjective", "d": "costing a lot of money", "e": "That watch is very expensive."}, {"a": "affordable", "b": "uh-FOR-duh-buul", "c": "adjective", "d": "reasonably priced", "e": "We found an affordable apartment."}, {"a": "save", "b": "SAYV", "c": "verb", "d": "to keep money for later instead of spending it", "e": "I am saving money for a trip."}, {"a": "refund", "b": "REE-fund", "c": "noun", "d": "money given back after a return", "e": "I got a refund for the broken item."}, {"a": "invoice", "b": "IN-voys", "c": "noun", "d": "a document listing what you must pay", "e": "Please send me the invoice."}], "tip": "Stress the first syllable in 'budget' and 'refund': BUH-jet, REE-fund.", "speaking": "Describe how you would plan a budget for a trip, using three of today's words.", "quiz": [{"type": "mcq", "q": "What does \"budget\" mean?", "options": ["a plan for how to spend money", "costing a lot of money", "reasonably priced", "to keep money for later instead of spending it"], "answer": 0, "explanation": "\"budget\" means a plan for how to spend money."}, {"type": "mcq", "q": "What does \"expensive\" mean?", "options": ["costing a lot of money", "a plan for how to spend money", "reasonably priced", "to keep money for later instead of spending it"], "answer": 0, "explanation": "\"expensive\" means costing a lot of money."}, {"type": "mcq", "q": "What does \"affordable\" mean?", "options": ["reasonably priced", "a plan for how to spend money", "costing a lot of money", "to keep money for later instead of spending it"], "answer": 0, "explanation": "\"affordable\" means reasonably priced."}, {"type": "mcq", "q": "What does \"save\" mean?", "options": ["to keep money for later instead of spending it", "a plan for how to spend money", "costing a lot of money", "reasonably priced"], "answer": 0, "explanation": "\"save\" means to keep money for later instead of spending it."}, {"type": "fill", "q": "I got a ____ for the broken item.", "answer": "refund", "explanation": "The word is \"refund\" — money given back after a return."}, {"type": "fill", "q": "Please send me the ____.", "answer": "invoice", "explanation": "The word is \"invoice\" — a document listing what you must pay."}]}, {"id": 37, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Technology Vocabulary", "focus": "Talking about devices and the internet", "type": "vocab", "intro": "Technology vocabulary is now part of daily conversation almost everywhere in the world.", "items": [{"a": "device", "b": "dee-VYSS", "c": "noun", "d": "a piece of equipment, like a phone or laptop", "e": "I bought a new device yesterday."}, {"a": "password", "b": "PASS-wurd", "c": "noun", "d": "a secret code to access an account", "e": "Please do not share your password."}, {"a": "upload", "b": "UP-lohd", "c": "verb", "d": "to send a file to the internet", "e": "I will upload the photos tonight."}, {"a": "download", "b": "DOWN-lohd", "c": "verb", "d": "to save a file from the internet to your device", "e": "Please download the app first."}, {"a": "battery", "b": "BAT-uh-ree", "c": "noun", "d": "the part that stores power in a device", "e": "My phone battery is almost dead."}, {"a": "connection", "b": "kuh-NEK-shun", "c": "noun", "d": "a link, especially to the internet", "e": "My internet connection is very slow."}], "tip": "'Upload' and 'download' are opposites — practise both directions in one sentence.", "speaking": "Explain how to use a common app, using three of today's tech words.", "quiz": [{"type": "mcq", "q": "What does \"device\" mean?", "options": ["a piece of equipment, like a phone or laptop", "a secret code to access an account", "to send a file to the internet", "to save a file from the internet to your device"], "answer": 0, "explanation": "\"device\" means a piece of equipment, like a phone or laptop."}, {"type": "mcq", "q": "What does \"password\" mean?", "options": ["a secret code to access an account", "a piece of equipment, like a phone or laptop", "to send a file to the internet", "to save a file from the internet to your device"], "answer": 0, "explanation": "\"password\" means a secret code to access an account."}, {"type": "mcq", "q": "What does \"upload\" mean?", "options": ["to send a file to the internet", "a piece of equipment, like a phone or laptop", "a secret code to access an account", "to save a file from the internet to your device"], "answer": 0, "explanation": "\"upload\" means to send a file to the internet."}, {"type": "mcq", "q": "What does \"download\" mean?", "options": ["to save a file from the internet to your device", "a piece of equipment, like a phone or laptop", "a secret code to access an account", "to send a file to the internet"], "answer": 0, "explanation": "\"download\" means to save a file from the internet to your device."}, {"type": "fill", "q": "My phone ____ is almost dead.", "answer": "battery", "explanation": "The word is \"battery\" — the part that stores power in a device."}, {"type": "fill", "q": "My internet ____ is very slow.", "answer": "connection", "explanation": "The word is \"connection\" — a link, especially to the internet."}]}, {"id": 38, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Health & Body (Intermediate)", "focus": "Beyond basic body words", "type": "vocab", "intro": "Building on Level 5, this level adds vocabulary for describing health in more detail.", "items": [{"a": "exhausted", "b": "eg-ZAWS-ted", "c": "adjective", "d": "extremely tired", "e": "After the long trip, I felt exhausted."}, {"a": "recover", "b": "ree-KUV-er", "c": "verb", "d": "to get better after illness", "e": "She is recovering from her surgery."}, {"a": "symptom", "b": "SIM-tum", "c": "noun", "d": "a sign that shows you are ill", "e": "A fever is a common symptom of the flu."}, {"a": "prescription", "b": "pri-SKRIP-shun", "c": "noun", "d": "a doctor's written order for medicine", "e": "The doctor gave me a prescription."}, {"a": "allergic", "b": "uh-LUR-jik", "c": "adjective", "d": "having a bad reaction to something", "e": "I am allergic to peanuts."}, {"a": "appointment", "b": "uh-POYNT-ment", "c": "noun", "d": "a planned meeting, often with a doctor", "e": "I have a doctor's appointment at 3pm."}], "tip": "'Exhausted' has a hidden 'z' sound: eg-ZAWS-ted, not eks-HOW-sted.", "speaking": "Describe a full visit to the doctor, from symptom to prescription, using today's words.", "quiz": [{"type": "mcq", "q": "What does \"exhausted\" mean?", "options": ["extremely tired", "to get better after illness", "a sign that shows you are ill", "a doctor's written order for medicine"], "answer": 0, "explanation": "\"exhausted\" means extremely tired."}, {"type": "mcq", "q": "What does \"recover\" mean?", "options": ["to get better after illness", "extremely tired", "a sign that shows you are ill", "a doctor's written order for medicine"], "answer": 0, "explanation": "\"recover\" means to get better after illness."}, {"type": "mcq", "q": "What does \"symptom\" mean?", "options": ["a sign that shows you are ill", "extremely tired", "to get better after illness", "a doctor's written order for medicine"], "answer": 0, "explanation": "\"symptom\" means a sign that shows you are ill."}, {"type": "mcq", "q": "What does \"prescription\" mean?", "options": ["a doctor's written order for medicine", "extremely tired", "to get better after illness", "a sign that shows you are ill"], "answer": 0, "explanation": "\"prescription\" means a doctor's written order for medicine."}, {"type": "fill", "q": "I am ____ to peanuts.", "answer": "allergic", "explanation": "The word is \"allergic\" — having a bad reaction to something."}, {"type": "fill", "q": "I have a doctor's ____ at 3pm.", "answer": "appointment", "explanation": "The word is \"appointment\" — a planned meeting, often with a doctor."}]}, {"id": 39, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Synonyms Practice", "focus": "Saying the same thing differently", "type": "vocab", "intro": "Knowing synonyms lets you avoid repeating the same word and sound more natural.", "items": [{"a": "happy / joyful", "b": "JOY-ful", "c": "adjective", "d": "feeling or showing great pleasure, a stronger version of happy", "e": "She felt joyful at the celebration."}, {"a": "big / enormous", "b": "ee-NOR-mus", "c": "adjective", "d": "extremely large, a stronger version of big", "e": "They live in an enormous house."}, {"a": "said / mentioned", "b": "MEN-shund", "c": "verb", "d": "referred to something briefly, a softer version of said", "e": "She mentioned the meeting was cancelled."}, {"a": "good / excellent", "b": "EK-suh-lent", "c": "adjective", "d": "extremely good, a stronger version of good", "e": "The food was excellent."}, {"a": "tired / weary", "b": "WEER-ee", "c": "adjective", "d": "very tired, especially after long effort, a literary version of tired", "e": "The travellers were weary after the journey."}, {"a": "start / commence", "b": "kuh-MENS", "c": "verb", "d": "to begin, a formal version of start", "e": "The ceremony will commence at 9am."}], "tip": "Formal synonyms like 'commence' are useful in writing and speeches, but 'start' is fine in daily talk.", "speaking": "Retell a short story you know, replacing three common words with their stronger synonyms.", "quiz": [{"type": "mcq", "q": "What does \"happy / joyful\" mean?", "options": ["feeling or showing great pleasure, a stronger version of happy", "extremely large, a stronger version of big", "referred to something briefly, a softer version of said", "extremely good, a stronger version of good"], "answer": 0, "explanation": "\"happy / joyful\" means feeling or showing great pleasure, a stronger version of happy."}, {"type": "mcq", "q": "What does \"big / enormous\" mean?", "options": ["extremely large, a stronger version of big", "feeling or showing great pleasure, a stronger version of happy", "referred to something briefly, a softer version of said", "extremely good, a stronger version of good"], "answer": 0, "explanation": "\"big / enormous\" means extremely large, a stronger version of big."}, {"type": "mcq", "q": "What does \"said / mentioned\" mean?", "options": ["referred to something briefly, a softer version of said", "feeling or showing great pleasure, a stronger version of happy", "extremely large, a stronger version of big", "extremely good, a stronger version of good"], "answer": 0, "explanation": "\"said / mentioned\" means referred to something briefly, a softer version of said."}, {"type": "mcq", "q": "What does \"good / excellent\" mean?", "options": ["extremely good, a stronger version of good", "feeling or showing great pleasure, a stronger version of happy", "extremely large, a stronger version of big", "referred to something briefly, a softer version of said"], "answer": 0, "explanation": "\"good / excellent\" means extremely good, a stronger version of good."}, {"type": "fill", "q": "The travellers were weary after the journey.", "answer": "tired / weary", "explanation": "The word is \"tired / weary\" — very tired, especially after long effort, a literary version of tired."}, {"type": "fill", "q": "The ceremony will commence at 9am.", "answer": "start / commence", "explanation": "The word is \"start / commence\" — to begin, a formal version of start."}]}, {"id": 40, "stage": "Stage 4 · Working Vocabulary", "stageName": "Stage 4 · Working Vocabulary", "title": "Antonyms Practice", "focus": "Understanding opposites", "type": "vocab", "intro": "Antonyms sharpen your understanding of meaning and give you more ways to describe contrast.", "items": [{"a": "generous ≠ stingy", "b": "STIN-jee", "c": "adjective", "d": "unwilling to spend or give money, the opposite of generous", "e": "He is too stingy to buy gifts."}, {"a": "brave ≠ cowardly", "b": "KOW-erd-lee", "c": "adjective", "d": "lacking courage, the opposite of brave", "e": "It was cowardly of him to run away."}, {"a": "simple ≠ complex", "b": "kom-PLEKS", "c": "adjective", "d": "difficult to understand, the opposite of simple", "e": "The instructions were quite complex."}, {"a": "ancient ≠ modern", "b": "MOD-ern", "c": "adjective", "d": "belonging to the present time, the opposite of ancient", "e": "They live in a modern apartment."}, {"a": "strict ≠ lenient", "b": "LEE-nee-ent", "c": "adjective", "d": "permissive and not strict, the opposite of strict", "e": "Our new teacher is very lenient."}, {"a": "rare ≠ common", "b": "KOM-un", "c": "adjective", "d": "happening often, the opposite of rare", "e": "Rain is common in this season."}], "tip": "Pairing new words with their opposite helps you remember both words twice as well.", "speaking": "Describe two people you know who are opposites, using an antonym pair.", "quiz": [{"type": "mcq", "q": "What does \"generous ≠ stingy\" mean?", "options": ["unwilling to spend or give money, the opposite of generous", "lacking courage, the opposite of brave", "difficult to understand, the opposite of simple", "belonging to the present time, the opposite of ancient"], "answer": 0, "explanation": "\"generous ≠ stingy\" means unwilling to spend or give money, the opposite of generous."}, {"type": "mcq", "q": "What does \"brave ≠ cowardly\" mean?", "options": ["lacking courage, the opposite of brave", "unwilling to spend or give money, the opposite of generous", "difficult to understand, the opposite of simple", "belonging to the present time, the opposite of ancient"], "answer": 0, "explanation": "\"brave ≠ cowardly\" means lacking courage, the opposite of brave."}, {"type": "mcq", "q": "What does \"simple ≠ complex\" mean?", "options": ["difficult to understand, the opposite of simple", "unwilling to spend or give money, the opposite of generous", "lacking courage, the opposite of brave", "belonging to the present time, the opposite of ancient"], "answer": 0, "explanation": "\"simple ≠ complex\" means difficult to understand, the opposite of simple."}, {"type": "mcq", "q": "What does \"ancient ≠ modern\" mean?", "options": ["belonging to the present time, the opposite of ancient", "unwilling to spend or give money, the opposite of generous", "lacking courage, the opposite of brave", "difficult to understand, the opposite of simple"], "answer": 0, "explanation": "\"ancient ≠ modern\" means belonging to the present time, the opposite of ancient."}, {"type": "fill", "q": "Our new teacher is very lenient.", "answer": "strict ≠ lenient", "explanation": "The word is \"strict ≠ lenient\" — permissive and not strict, the opposite of strict."}, {"type": "fill", "q": "Rain is common in this season.", "answer": "rare ≠ common", "explanation": "The word is \"rare ≠ common\" — happening often, the opposite of rare."}]}, {"id": 41, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Academic Words I", "focus": "Vocabulary for serious topics", "type": "advanced", "intro": "These words appear often in news, essays, and formal discussions — using them well signals advanced fluency.", "items": [{"a": "significant", "b": "sig-NIF-i-kant", "c": "important enough to be noticed or to matter", "d": "There has been a significant improvement in her English."}, {"a": "approach", "b": "uh-PROHCH", "c": "a way of dealing with something", "d": "We need a new approach to this problem."}, {"a": "perspective", "b": "per-SPEK-tiv", "c": "a particular way of viewing something, based on experience", "d": "Try to see it from her perspective."}, {"a": "consequence", "b": "KON-si-kwens", "c": "a result or effect of an action", "d": "Every choice has a consequence."}, {"a": "strategy", "b": "STRAT-uh-jee", "c": "a plan of action to achieve a goal", "d": "We need a clear strategy to finish this project."}, {"a": "evidence", "b": "EV-i-dens", "c": "facts or information that prove something is true", "d": "There is strong evidence to support the theory."}], "tip": "Break long words into parts: per-SPEC-tive, con-SE-quence — stress usually falls on the second syllable.", "speaking": "Give your opinion on a current topic using at least two of these academic words.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"significant\"?", "options": ["important enough to be noticed or to matter", "a way of dealing with something", "a particular way of viewing something, based on experience", "a result or effect of an action"], "answer": 0, "explanation": "\"significant\" — important enough to be noticed or to matter"}, {"type": "mcq", "q": "What is the closest meaning of \"approach\"?", "options": ["a way of dealing with something", "important enough to be noticed or to matter", "a particular way of viewing something, based on experience", "a result or effect of an action"], "answer": 0, "explanation": "\"approach\" — a way of dealing with something"}, {"type": "mcq", "q": "What is the closest meaning of \"perspective\"?", "options": ["a particular way of viewing something, based on experience", "important enough to be noticed or to matter", "a way of dealing with something", "a result or effect of an action"], "answer": 0, "explanation": "\"perspective\" — a particular way of viewing something, based on experience"}, {"type": "mcq", "q": "What is the closest meaning of \"consequence\"?", "options": ["a result or effect of an action", "important enough to be noticed or to matter", "a way of dealing with something", "a particular way of viewing something, based on experience"], "answer": 0, "explanation": "\"consequence\" — a result or effect of an action"}, {"type": "fill", "q": "We need a clear ____ to finish this project.", "answer": "strategy", "explanation": "strategy: a plan of action to achieve a goal"}, {"type": "fill", "q": "There is strong ____ to support the theory.", "answer": "evidence", "explanation": "evidence: facts or information that prove something is true"}]}, {"id": 42, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Academic Words II", "focus": "Expanding your formal vocabulary", "type": "advanced", "intro": "This continues building the vocabulary you need for debates, essays, and professional discussion.", "items": [{"a": "inevitable", "b": "in-EV-i-tuh-buul", "c": "certain to happen; impossible to avoid", "d": "Change was inevitable in that industry."}, {"a": "substantial", "b": "sub-STAN-shul", "c": "large in size, value, or importance", "d": "There was a substantial increase in sales."}, {"a": "controversial", "b": "kon-truh-VUR-shul", "c": "causing strong disagreement", "d": "It was a controversial decision."}, {"a": "innovative", "b": "IN-uh-vay-tiv", "c": "introducing new ideas or methods", "d": "The company is known for innovative products."}, {"a": "collaborate", "b": "kuh-LAB-uh-rayt", "c": "to work together with others on a task", "d": "We plan to collaborate on this project."}, {"a": "sustainable", "b": "suh-STAY-nuh-buul", "c": "able to continue over time without harming resources", "d": "We need more sustainable farming methods."}], "tip": "For long words, first find the stressed syllable, say it loudly, then build the rest of the word around it.", "speaking": "Discuss a topic you care about — environment, technology, or education — using three of these words.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"inevitable\"?", "options": ["certain to happen; impossible to avoid", "large in size, value, or importance", "causing strong disagreement", "introducing new ideas or methods"], "answer": 0, "explanation": "\"inevitable\" — certain to happen; impossible to avoid"}, {"type": "mcq", "q": "What is the closest meaning of \"substantial\"?", "options": ["large in size, value, or importance", "certain to happen; impossible to avoid", "causing strong disagreement", "introducing new ideas or methods"], "answer": 0, "explanation": "\"substantial\" — large in size, value, or importance"}, {"type": "mcq", "q": "What is the closest meaning of \"controversial\"?", "options": ["causing strong disagreement", "certain to happen; impossible to avoid", "large in size, value, or importance", "introducing new ideas or methods"], "answer": 0, "explanation": "\"controversial\" — causing strong disagreement"}, {"type": "mcq", "q": "What is the closest meaning of \"innovative\"?", "options": ["introducing new ideas or methods", "certain to happen; impossible to avoid", "large in size, value, or importance", "causing strong disagreement"], "answer": 0, "explanation": "\"innovative\" — introducing new ideas or methods"}, {"type": "fill", "q": "We plan to ____ on this project.", "answer": "collaborate", "explanation": "collaborate: to work together with others on a task"}, {"type": "fill", "q": "We need more ____ farming methods.", "answer": "sustainable", "explanation": "sustainable: able to continue over time without harming resources"}]}, {"id": 43, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Everyday Idioms I", "focus": "Common expressions natives use", "type": "advanced", "intro": "Idioms don't mean what their individual words suggest — learning them helps you understand real conversation.", "items": [{"a": "break the ice", "b": "brayk thee EYSS", "c": "to make people feel comfortable at the start of a meeting", "d": "He told a joke to break the ice."}, {"a": "piece of cake", "b": "peess uv KAYK", "c": "something very easy to do", "d": "The test was a piece of cake."}, {"a": "under the weather", "b": "UN-der thuh WETH-er", "c": "feeling slightly ill", "d": "I'm feeling a bit under the weather today."}, {"a": "hit the books", "b": "hit thuh BUKS", "c": "to study hard", "d": "I need to hit the books before the exam."}, {"a": "cost an arm and a leg", "b": "kost an ARM and uh LEG", "c": "to be very expensive", "d": "That new phone cost an arm and a leg."}, {"a": "once in a blue moon", "b": "wuns in uh BLOO moon", "c": "very rarely", "d": "We only meet once in a blue moon."}], "tip": "Idioms are usually said as one smooth phrase with natural rhythm — practise them as whole chunks, not word by word.", "speaking": "Try to use two idioms naturally while describing your week.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"break the ice\"?", "options": ["to make people feel comfortable at the start of a meeting", "something very easy to do", "feeling slightly ill", "to study hard"], "answer": 0, "explanation": "\"break the ice\" — to make people feel comfortable at the start of a meeting"}, {"type": "mcq", "q": "What is the closest meaning of \"piece of cake\"?", "options": ["something very easy to do", "to make people feel comfortable at the start of a meeting", "feeling slightly ill", "to study hard"], "answer": 0, "explanation": "\"piece of cake\" — something very easy to do"}, {"type": "mcq", "q": "What is the closest meaning of \"under the weather\"?", "options": ["feeling slightly ill", "to make people feel comfortable at the start of a meeting", "something very easy to do", "to study hard"], "answer": 0, "explanation": "\"under the weather\" — feeling slightly ill"}, {"type": "mcq", "q": "What is the closest meaning of \"hit the books\"?", "options": ["to study hard", "to make people feel comfortable at the start of a meeting", "something very easy to do", "feeling slightly ill"], "answer": 0, "explanation": "\"hit the books\" — to study hard"}, {"type": "fill", "q": "That new phone ____.", "answer": "cost an arm and a leg", "explanation": "cost an arm and a leg: to be very expensive"}, {"type": "fill", "q": "We only meet ____.", "answer": "once in a blue moon", "explanation": "once in a blue moon: very rarely"}]}, {"id": 44, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Everyday Idioms II", "focus": "More natural expressions", "type": "advanced", "intro": "This second set of idioms adds more color and personality to your spoken English.", "items": [{"a": "bite the bullet", "b": "byt thuh BUL-it", "c": "to force yourself to do something difficult", "d": "I finally bit the bullet and applied for the job."}, {"a": "let the cat out of the bag", "b": "let thuh KAT owt uv thuh bag", "c": "to accidentally reveal a secret", "d": "She let the cat out of the bag about the surprise party."}, {"a": "on the same page", "b": "on thuh SAYM payj", "c": "having the same understanding or opinion", "d": "Let's make sure we're on the same page before the meeting."}, {"a": "call it a day", "b": "kawl it uh DAY", "c": "to stop working on something for now", "d": "We've done enough for today; let's call it a day."}, {"a": "get the ball rolling", "b": "get thuh BAWL ROH-ling", "c": "to start a process or activity", "d": "Let's get the ball rolling on this project."}, {"a": "miss the boat", "b": "miss thuh BOHT", "c": "to lose a chance to do something", "d": "If you don't apply now, you might miss the boat."}], "tip": "Try recording yourself using one idiom in a full, natural sentence, then listen back.", "speaking": "Tell a short story about your week using at least two idioms from today's list.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"bite the bullet\"?", "options": ["to force yourself to do something difficult", "to accidentally reveal a secret", "having the same understanding or opinion", "to stop working on something for now"], "answer": 0, "explanation": "\"bite the bullet\" — to force yourself to do something difficult"}, {"type": "mcq", "q": "What is the closest meaning of \"let the cat out of the bag\"?", "options": ["to accidentally reveal a secret", "to force yourself to do something difficult", "having the same understanding or opinion", "to stop working on something for now"], "answer": 0, "explanation": "\"let the cat out of the bag\" — to accidentally reveal a secret"}, {"type": "mcq", "q": "What is the closest meaning of \"on the same page\"?", "options": ["having the same understanding or opinion", "to force yourself to do something difficult", "to accidentally reveal a secret", "to stop working on something for now"], "answer": 0, "explanation": "\"on the same page\" — having the same understanding or opinion"}, {"type": "mcq", "q": "What is the closest meaning of \"call it a day\"?", "options": ["to stop working on something for now", "to force yourself to do something difficult", "to accidentally reveal a secret", "having the same understanding or opinion"], "answer": 0, "explanation": "\"call it a day\" — to stop working on something for now"}, {"type": "fill", "q": "Let's ____ on this project.", "answer": "get the ball rolling", "explanation": "get the ball rolling: to start a process or activity"}, {"type": "fill", "q": "If you don't apply now, you might ____.", "answer": "miss the boat", "explanation": "miss the boat: to lose a chance to do something"}]}, {"id": 45, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Business English", "focus": "Professional expressions", "type": "advanced", "intro": "These phrases will help you sound polished and professional in meetings and emails.", "items": [{"a": "touch base", "b": "tuch BAYSS", "c": "to make brief contact with someone to check progress", "d": "Let's touch base next week about the project."}, {"a": "circle back", "b": "SUR-kul bak", "c": "to return to a topic later", "d": "We'll circle back to this point after lunch."}, {"a": "bandwidth", "b": "BAND-width", "c": "the time or capacity to take on more work", "d": "I don't have the bandwidth for another project right now."}, {"a": "streamline", "b": "STREEM-lyn", "c": "to make a process simpler and more efficient", "d": "We need to streamline our approval process."}, {"a": "stakeholder", "b": "STAYK-hohl-der", "c": "a person with an interest in a project's outcome", "d": "We must inform all stakeholders before the launch."}, {"a": "actionable", "b": "AK-shun-uh-buul", "c": "practical enough to be acted upon", "d": "Please give me actionable feedback."}], "tip": "Business phrases are often said briskly and confidently — practise them with a firm, steady tone.", "speaking": "Write and say one professional sentence for each of three phrases above, as if in a meeting.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"touch base\"?", "options": ["to make brief contact with someone to check progress", "to return to a topic later", "the time or capacity to take on more work", "to make a process simpler and more efficient"], "answer": 0, "explanation": "\"touch base\" — to make brief contact with someone to check progress"}, {"type": "mcq", "q": "What is the closest meaning of \"circle back\"?", "options": ["to return to a topic later", "to make brief contact with someone to check progress", "the time or capacity to take on more work", "to make a process simpler and more efficient"], "answer": 0, "explanation": "\"circle back\" — to return to a topic later"}, {"type": "mcq", "q": "What is the closest meaning of \"bandwidth\"?", "options": ["the time or capacity to take on more work", "to make brief contact with someone to check progress", "to return to a topic later", "to make a process simpler and more efficient"], "answer": 0, "explanation": "\"bandwidth\" — the time or capacity to take on more work"}, {"type": "mcq", "q": "What is the closest meaning of \"streamline\"?", "options": ["to make a process simpler and more efficient", "to make brief contact with someone to check progress", "to return to a topic later", "the time or capacity to take on more work"], "answer": 0, "explanation": "\"streamline\" — to make a process simpler and more efficient"}, {"type": "fill", "q": "We must inform all ____s before the launch.", "answer": "stakeholder", "explanation": "stakeholder: a person with an interest in a project's outcome"}, {"type": "fill", "q": "Please give me ____ feedback.", "answer": "actionable", "explanation": "actionable: practical enough to be acted upon"}]}, {"id": 46, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Formal vs Informal English", "focus": "Choosing the right register", "type": "advanced", "intro": "Fluent speakers switch tone depending on the situation. This level trains you to recognize both.", "items": [{"a": "purchase (formal) / buy (informal)", "b": "PUR-chuss", "c": "to obtain something in exchange for money", "d": "Formal: 'I would like to purchase this item.' Informal: 'I want to buy this.'"}, {"a": "commence (formal) / start (informal)", "b": "kuh-MENS", "c": "to begin", "d": "Formal: 'The event will commence at 6pm.' Informal: 'It starts at 6.'"}, {"a": "assist (formal) / help (informal)", "b": "uh-SIST", "c": "to give support to someone", "d": "Formal: 'May I assist you?' Informal: 'Need help?'"}, {"a": "residence (formal) / home (informal)", "b": "REZ-i-dens", "c": "the place where someone lives", "d": "Formal: 'This is my residence.' Informal: 'This is my home.'"}, {"a": "inquire (formal) / ask (informal)", "b": "in-KWYR", "c": "to request information", "d": "Formal: 'I would like to inquire about the price.' Informal: 'Can I ask about the price?'"}, {"a": "regarding (formal) / about (informal)", "b": "ree-GARD-ing", "c": "concerning a particular topic", "d": "Formal: 'Regarding your email...' Informal: 'About your email...'"}], "tip": "Use formal words in emails and interviews, and informal words with friends — mixing them can sound odd.", "speaking": "Say the same request in both a formal and an informal way, for two different situations.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"purchase (formal) / buy (informal)\"?", "options": ["to obtain something in exchange for money", "to begin", "to give support to someone", "the place where someone lives"], "answer": 0, "explanation": "\"purchase (formal) / buy (informal)\" — to obtain something in exchange for money"}, {"type": "mcq", "q": "What is the closest meaning of \"commence (formal) / start (informal)\"?", "options": ["to begin", "to obtain something in exchange for money", "to give support to someone", "the place where someone lives"], "answer": 0, "explanation": "\"commence (formal) / start (informal)\" — to begin"}, {"type": "mcq", "q": "What is the closest meaning of \"assist (formal) / help (informal)\"?", "options": ["to give support to someone", "to obtain something in exchange for money", "to begin", "the place where someone lives"], "answer": 0, "explanation": "\"assist (formal) / help (informal)\" — to give support to someone"}, {"type": "mcq", "q": "What is the closest meaning of \"residence (formal) / home (informal)\"?", "options": ["the place where someone lives", "to obtain something in exchange for money", "to begin", "to give support to someone"], "answer": 0, "explanation": "\"residence (formal) / home (informal)\" — the place where someone lives"}, {"type": "fill", "q": "Formal: 'I would like to inquire about the price.' Informal: 'Can I ask about the price?'", "answer": "inquire (formal) / ask (informal)", "explanation": "inquire (formal) / ask (informal): to request information"}, {"type": "fill", "q": "Formal: 'Regarding your email...' Informal: 'About your email...'", "answer": "regarding (formal) / about (informal)", "explanation": "regarding (formal) / about (informal): concerning a particular topic"}]}, {"id": 47, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Advanced Connectors", "focus": "Sounding sophisticated in speech", "type": "advanced", "intro": "These connectors are common in debates, presentations, and advanced writing — use them to link complex ideas.", "items": [{"a": "nevertheless", "b": "nev-er-thuh-LESS", "c": "despite what was just said; however", "d": "The plan was risky; nevertheless, we proceeded."}, {"a": "furthermore", "b": "FUR-ther-mor", "c": "in addition; used to add a further point", "d": "The product is affordable; furthermore, it is durable."}, {"a": "consequently", "b": "KON-si-kwent-lee", "c": "as a result", "d": "He missed the deadline; consequently, he lost the contract."}, {"a": "on the other hand", "b": "on thee UH-ther hand", "c": "used to introduce a contrasting point", "d": "I enjoy the city; on the other hand, I miss the quiet countryside."}, {"a": "in contrast", "b": "in KON-trast", "c": "used to show a difference between two things", "d": "In contrast to last year, sales have improved."}, {"a": "as a result", "b": "az uh ri-ZULT", "c": "shows the effect or outcome of something", "d": "It rained heavily; as a result, the match was cancelled."}], "tip": "Pause briefly before and after connectors like 'nevertheless' to give them weight in speech.", "speaking": "Give a two-sentence opinion on any topic, linking your ideas with 'however' or 'consequently'.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"nevertheless\"?", "options": ["despite what was just said; however", "in addition; used to add a further point", "as a result", "used to introduce a contrasting point"], "answer": 0, "explanation": "\"nevertheless\" — despite what was just said; however"}, {"type": "mcq", "q": "What is the closest meaning of \"furthermore\"?", "options": ["in addition; used to add a further point", "despite what was just said; however", "as a result", "used to introduce a contrasting point"], "answer": 0, "explanation": "\"furthermore\" — in addition; used to add a further point"}, {"type": "mcq", "q": "What is the closest meaning of \"consequently\"?", "options": ["as a result", "despite what was just said; however", "in addition; used to add a further point", "used to introduce a contrasting point"], "answer": 0, "explanation": "\"consequently\" — as a result"}, {"type": "mcq", "q": "What is the closest meaning of \"on the other hand\"?", "options": ["used to introduce a contrasting point", "despite what was just said; however", "in addition; used to add a further point", "as a result"], "answer": 0, "explanation": "\"on the other hand\" — used to introduce a contrasting point"}, {"type": "fill", "q": "In contrast to last year, sales have improved.", "answer": "in contrast", "explanation": "in contrast: used to show a difference between two things"}, {"type": "fill", "q": "It rained heavily; ____, the match was cancelled.", "answer": "as a result", "explanation": "as a result: shows the effect or outcome of something"}]}, {"id": 48, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Descriptive Adjectives", "focus": "Painting a picture with words", "type": "advanced", "intro": "Rich adjectives make your descriptions more vivid and interesting than basic words like 'nice' or 'bad'.", "items": [{"a": "breathtaking", "b": "BRETH-tay-king", "c": "extremely beautiful or amazing", "d": "The view from the mountain was breathtaking."}, {"a": "meticulous", "b": "muh-TIK-yoo-lus", "c": "showing great attention to detail", "d": "She is meticulous about her work."}, {"a": "eloquent", "b": "EL-uh-kwent", "c": "fluent and persuasive in speaking", "d": "He gave an eloquent speech at the ceremony."}, {"a": "resilient", "b": "ree-ZIL-yent", "c": "able to recover quickly from difficulties", "d": "Children are often remarkably resilient."}, {"a": "versatile", "b": "VUR-suh-tyl", "c": "able to adapt to many different functions", "d": "She is a versatile actress who can play any role."}, {"a": "ambiguous", "b": "am-BIG-yoo-us", "c": "unclear or open to more than one meaning", "d": "His answer was rather ambiguous."}], "tip": "Descriptive adjectives carry emotional weight — say them with matching facial expression and tone.", "speaking": "Describe a place, a person, and an experience, using one advanced adjective each.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"breathtaking\"?", "options": ["extremely beautiful or amazing", "showing great attention to detail", "fluent and persuasive in speaking", "able to recover quickly from difficulties"], "answer": 0, "explanation": "\"breathtaking\" — extremely beautiful or amazing"}, {"type": "mcq", "q": "What is the closest meaning of \"meticulous\"?", "options": ["showing great attention to detail", "extremely beautiful or amazing", "fluent and persuasive in speaking", "able to recover quickly from difficulties"], "answer": 0, "explanation": "\"meticulous\" — showing great attention to detail"}, {"type": "mcq", "q": "What is the closest meaning of \"eloquent\"?", "options": ["fluent and persuasive in speaking", "extremely beautiful or amazing", "showing great attention to detail", "able to recover quickly from difficulties"], "answer": 0, "explanation": "\"eloquent\" — fluent and persuasive in speaking"}, {"type": "mcq", "q": "What is the closest meaning of \"resilient\"?", "options": ["able to recover quickly from difficulties", "extremely beautiful or amazing", "showing great attention to detail", "fluent and persuasive in speaking"], "answer": 0, "explanation": "\"resilient\" — able to recover quickly from difficulties"}, {"type": "fill", "q": "She is a ____ actress who can play any role.", "answer": "versatile", "explanation": "versatile: able to adapt to many different functions"}, {"type": "fill", "q": "His answer was rather ____.", "answer": "ambiguous", "explanation": "ambiguous: unclear or open to more than one meaning"}]}, {"id": 49, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Commonly Confused Words", "focus": "Getting tricky pairs right", "type": "advanced", "intro": "These word pairs are frequently mixed up, even by advanced learners — mastering them boosts precision.", "items": [{"a": "affect / effect", "b": "uh-FEKT / ee-FEKT", "c": "'affect' is usually a verb (to influence); 'effect' is usually a noun (a result)", "d": "The weather can affect your mood. / The effect was immediate."}, {"a": "advice / advise", "b": "ad-VYSS / ad-VYZ", "c": "'advice' is a noun (a suggestion); 'advise' is a verb (to suggest)", "d": "She gave me good advice. / He advised me to rest."}, {"a": "borrow / lend", "b": "BOR-oh / LEND", "c": "'borrow' means to take temporarily; 'lend' means to give temporarily", "d": "Can I borrow your pen? / Can you lend me your pen?"}, {"a": "say / tell", "b": "SAY / TEL", "c": "'say' does not need an object; 'tell' needs a person as an object", "d": "She said hello. / She told me a story."}, {"a": "its / it's", "b": "its / its", "c": "'its' shows possession; 'it's' is short for 'it is'", "d": "The dog wagged its tail. / It's raining today."}, {"a": "lose / loose", "b": "LOOZ / LOOSS", "c": "'lose' means to misplace or fail to win; 'loose' means not tight", "d": "Don't lose your keys. / These shoes are too loose."}], "tip": "Say each pair aloud back-to-back — hearing the sound difference helps you remember which is which.", "speaking": "Make one correct sentence with each word in three of today's pairs.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"affect / effect\"?", "options": ["'affect' is usually a verb (to influence); 'effect' is usually a noun (a result)", "'advice' is a noun (a suggestion); 'advise' is a verb (to suggest)", "'borrow' means to take temporarily; 'lend' means to give temporarily", "'say' does not need an object; 'tell' needs a person as an object"], "answer": 0, "explanation": "\"affect / effect\" — 'affect' is usually a verb (to influence); 'effect' is usually a noun (a result)"}, {"type": "mcq", "q": "What is the closest meaning of \"advice / advise\"?", "options": ["'advice' is a noun (a suggestion); 'advise' is a verb (to suggest)", "'affect' is usually a verb (to influence); 'effect' is usually a noun (a result)", "'borrow' means to take temporarily; 'lend' means to give temporarily", "'say' does not need an object; 'tell' needs a person as an object"], "answer": 0, "explanation": "\"advice / advise\" — 'advice' is a noun (a suggestion); 'advise' is a verb (to suggest)"}, {"type": "mcq", "q": "What is the closest meaning of \"borrow / lend\"?", "options": ["'borrow' means to take temporarily; 'lend' means to give temporarily", "'affect' is usually a verb (to influence); 'effect' is usually a noun (a result)", "'advice' is a noun (a suggestion); 'advise' is a verb (to suggest)", "'say' does not need an object; 'tell' needs a person as an object"], "answer": 0, "explanation": "\"borrow / lend\" — 'borrow' means to take temporarily; 'lend' means to give temporarily"}, {"type": "mcq", "q": "What is the closest meaning of \"say / tell\"?", "options": ["'say' does not need an object; 'tell' needs a person as an object", "'affect' is usually a verb (to influence); 'effect' is usually a noun (a result)", "'advice' is a noun (a suggestion); 'advise' is a verb (to suggest)", "'borrow' means to take temporarily; 'lend' means to give temporarily"], "answer": 0, "explanation": "\"say / tell\" — 'say' does not need an object; 'tell' needs a person as an object"}, {"type": "fill", "q": "The dog wagged its tail. / It's raining today.", "answer": "its / it's", "explanation": "its / it's: 'its' shows possession; 'it's' is short for 'it is'"}, {"type": "fill", "q": "Don't lose your keys. / These shoes are too loose.", "answer": "lose / loose", "explanation": "lose / loose: 'lose' means to misplace or fail to win; 'loose' means not tight"}]}, {"id": 50, "stage": "Stage 5 · Advanced Words & Idioms", "stageName": "Stage 5 · Advanced Words & Idioms", "title": "Proverbs & Wisdom Sayings", "focus": "Timeless expressions", "type": "advanced", "intro": "Proverbs carry cultural wisdom in short, memorable form — using them naturally shows deep fluency.", "items": [{"a": "Practice makes perfect.", "b": "PRAK-tiss mayks PUR-fekt", "c": "the more you practise something, the better you become", "d": "Don't worry about mistakes — practice makes perfect."}, {"a": "Better late than never.", "b": "BET-er LAYT than NEV-er", "c": "it is better to do something late than not at all", "d": "He finally called to apologize — better late than never."}, {"a": "Actions speak louder than words.", "b": "AK-shunz speek LOW-der than WURDZ", "c": "what you do matters more than what you say", "d": "He promised to help, but actions speak louder than words."}, {"a": "Every cloud has a silver lining.", "b": "EV-ree klowd haz uh SIL-ver LY-ning", "c": "there is something good in every bad situation", "d": "I lost my job, but every cloud has a silver lining — I found a better one."}, {"a": "Don't judge a book by its cover.", "b": "dohnt JUJ uh buk by its KUV-er", "c": "don't judge something only by appearance", "d": "He looked serious, but don't judge a book by its cover."}, {"a": "The early bird catches the worm.", "b": "thee UR-lee burd KACH-iz thuh WURM", "c": "people who act early gain an advantage", "d": "I applied for the job first thing — the early bird catches the worm."}], "tip": "Proverbs are said with confident, even rhythm — practise them like short poems.", "speaking": "Choose one proverb and explain a real situation from your life where it applies.", "quiz": [{"type": "mcq", "q": "What is the closest meaning of \"Practice makes perfect.\"?", "options": ["the more you practise something, the better you become", "it is better to do something late than not at all", "what you do matters more than what you say", "there is something good in every bad situation"], "answer": 0, "explanation": "\"Practice makes perfect.\" — the more you practise something, the better you become"}, {"type": "mcq", "q": "What is the closest meaning of \"Better late than never.\"?", "options": ["it is better to do something late than not at all", "the more you practise something, the better you become", "what you do matters more than what you say", "there is something good in every bad situation"], "answer": 0, "explanation": "\"Better late than never.\" — it is better to do something late than not at all"}, {"type": "mcq", "q": "What is the closest meaning of \"Actions speak louder than words.\"?", "options": ["what you do matters more than what you say", "the more you practise something, the better you become", "it is better to do something late than not at all", "there is something good in every bad situation"], "answer": 0, "explanation": "\"Actions speak louder than words.\" — what you do matters more than what you say"}, {"type": "mcq", "q": "What is the closest meaning of \"Every cloud has a silver lining.\"?", "options": ["there is something good in every bad situation", "the more you practise something, the better you become", "it is better to do something late than not at all", "what you do matters more than what you say"], "answer": 0, "explanation": "\"Every cloud has a silver lining.\" — there is something good in every bad situation"}, {"type": "fill", "q": "He looked serious, but don't judge a book by its cover.", "answer": "Don't judge a book by its cover.", "explanation": "Don't judge a book by its cover.: don't judge something only by appearance"}, {"type": "fill", "q": "I applied for the job first thing — the early bird catches the worm.", "answer": "The early bird catches the worm.", "explanation": "The early bird catches the worm.: people who act early gain an advantage"}]}, {"id": 51, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Telling a Story", "focus": "Structuring a spoken narrative", "type": "fluency", "intro": "By now you have strong vocabulary and grammar. This stage focuses purely on speaking longer and more confidently.", "items": [{"a": "Starting a story", "c": "So, let me tell you what happened yesterday..."}, {"a": "Adding a twist", "c": "But then, out of nowhere, something unexpected happened."}, {"a": "Building tension", "c": "I honestly didn't know what to do at that moment."}, {"a": "Reaching the climax", "c": "And that's when everything suddenly made sense."}, {"a": "Ending a story", "c": "In the end, it all worked out for the best."}, {"a": "Reflecting afterward", "c": "Looking back, I'm really glad it happened that way."}], "tip": "Vary your speaking speed: slow down for important moments, and speed up for fast action.", "speaking": "Tell a two-minute story about something that really happened to you, using at least four phrases above.", "quiz": [{"type": "fill", "q": "So, let me tell you what happened ____", "answer": "yesterday...", "explanation": "Useful phrase: \"So, let me tell you what happened yesterday...\""}, {"type": "fill", "q": "But then, out of nowhere, something ____ happened.", "answer": "unexpected", "explanation": "Useful phrase: \"But then, out of nowhere, something unexpected happened.\""}, {"type": "fill", "q": "I ____ didn't know what to do at that moment.", "answer": "honestly", "explanation": "Useful phrase: \"I honestly didn't know what to do at that moment.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Reaching the climax\"?", "options": ["And that's when everything suddenly made sense.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "And that's when everything suddenly made sense."}, {"type": "mcq", "q": "Which phrase best fits: \"Ending a story\"?", "options": ["In the end, it all worked out for the best.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "In the end, it all worked out for the best."}, {"type": "mcq", "q": "Which phrase best fits: \"Reflecting afterward\"?", "options": ["Looking back, I'm really glad it happened that way.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Looking back, I'm really glad it happened that way."}]}, {"id": 52, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Expressing Opinions", "focus": "Sharing your point of view clearly", "type": "fluency", "intro": "Confident speakers state opinions clearly and support them — this is a core fluency skill.", "items": [{"a": "Giving an opinion", "c": "In my opinion, remote work is more productive."}, {"a": "Softening an opinion", "c": "I could be wrong, but I think this plan needs more time."}, {"a": "Being direct", "c": "Honestly, I don't agree with that approach."}, {"a": "Asking for someone's opinion", "c": "What's your take on this?"}, {"a": "Adding a reason", "c": "The main reason I think this is that it saves time."}, {"a": "Concluding an opinion", "c": "That's why I believe this is the right choice."}], "tip": "State your opinion, then pause briefly before giving your reason — this pause adds confidence and clarity.", "speaking": "Give your opinion on a topic you care about, with two supporting reasons, for one full minute.", "quiz": [{"type": "fill", "q": "In my opinion, remote work is more ____", "answer": "productive.", "explanation": "Useful phrase: \"In my opinion, remote work is more productive.\""}, {"type": "fill", "q": "I ____ be wrong, but I think this plan needs more time.", "answer": "could", "explanation": "Useful phrase: \"I could be wrong, but I think this plan needs more time.\""}, {"type": "fill", "q": "Honestly, I don't agree with that ____", "answer": "approach.", "explanation": "Useful phrase: \"Honestly, I don't agree with that approach.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Asking for someone's opinion\"?", "options": ["What's your take on this?", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "What's your take on this?"}, {"type": "mcq", "q": "Which phrase best fits: \"Adding a reason\"?", "options": ["The main reason I think this is that it saves time.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "The main reason I think this is that it saves time."}, {"type": "mcq", "q": "Which phrase best fits: \"Concluding an opinion\"?", "options": ["That's why I believe this is the right choice.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "That's why I believe this is the right choice."}]}, {"id": 53, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Agreeing & Disagreeing", "focus": "Handling different viewpoints politely", "type": "fluency", "intro": "Being able to disagree politely, without losing confidence, is a mark of true fluency.", "items": [{"a": "Agreeing strongly", "c": "I completely agree with you on that."}, {"a": "Agreeing partly", "c": "That's a fair point, but I see it a bit differently."}, {"a": "Disagreeing politely", "c": "I understand your point, but I have to disagree."}, {"a": "Asking for clarification", "c": "Could you explain what you mean by that?"}, {"a": "Offering a compromise", "c": "Maybe we could find a middle ground here."}, {"a": "Ending a disagreement gracefully", "c": "Let's agree to disagree on this one."}], "tip": "Keep your tone calm and warm even when disagreeing — the words matter less than the tone.", "speaking": "Debate a simple topic (tea vs coffee, city vs village life) for one minute, arguing one side.", "quiz": [{"type": "fill", "q": "I ____ agree with you on that.", "answer": "completely", "explanation": "Useful phrase: \"I completely agree with you on that.\""}, {"type": "fill", "q": "That's a fair point, but I see it a bit ____", "answer": "differently.", "explanation": "Useful phrase: \"That's a fair point, but I see it a bit differently.\""}, {"type": "fill", "q": "I ____ your point, but I have to disagree.", "answer": "understand", "explanation": "Useful phrase: \"I understand your point, but I have to disagree.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Asking for clarification\"?", "options": ["Could you explain what you mean by that?", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Could you explain what you mean by that?"}, {"type": "mcq", "q": "Which phrase best fits: \"Offering a compromise\"?", "options": ["Maybe we could find a middle ground here.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Maybe we could find a middle ground here."}, {"type": "mcq", "q": "Which phrase best fits: \"Ending a disagreement gracefully\"?", "options": ["Let's agree to disagree on this one.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Let's agree to disagree on this one."}]}, {"id": 54, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Debate Practice I", "focus": "Arguing a position confidently", "type": "fluency", "intro": "This level trains you to build and defend an argument out loud — a powerful fluency exercise.", "items": [{"a": "Stating your position", "c": "I firmly believe that technology has improved our lives."}, {"a": "Giving evidence", "c": "For example, we can now learn any skill online for free."}, {"a": "Addressing a counter-argument", "c": "Some people say it isolates us, but I think it connects us more."}, {"a": "Strengthening your point", "c": "Moreover, technology has made healthcare far more accessible."}, {"a": "Summarizing", "c": "For all these reasons, I stand by my position."}, {"a": "Inviting response", "c": "I'd love to hear a different perspective on this."}], "tip": "In debate, speak a little slower than usual and use strong, clear stress on your key words.", "speaking": "Argue for two minutes: 'Is social media good or bad for society?' Pick one side and defend it fully.", "quiz": [{"type": "fill", "q": "I firmly believe that ____ has improved our lives.", "answer": "technology", "explanation": "Useful phrase: \"I firmly believe that technology has improved our lives.\""}, {"type": "fill", "q": "For ____, we can now learn any skill online for free.", "answer": "example", "explanation": "Useful phrase: \"For example, we can now learn any skill online for free.\""}, {"type": "fill", "q": "Some people say it ____ us, but I think it connects us more.", "answer": "isolates", "explanation": "Useful phrase: \"Some people say it isolates us, but I think it connects us more.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Strengthening your point\"?", "options": ["Moreover, technology has made healthcare far more accessible.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Moreover, technology has made healthcare far more accessible."}, {"type": "mcq", "q": "Which phrase best fits: \"Summarizing\"?", "options": ["For all these reasons, I stand by my position.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "For all these reasons, I stand by my position."}, {"type": "mcq", "q": "Which phrase best fits: \"Inviting response\"?", "options": ["I'd love to hear a different perspective on this.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "I'd love to hear a different perspective on this."}]}, {"id": 55, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Debate Practice II", "focus": "A harder topic, longer speech", "type": "fluency", "intro": "This level raises the difficulty with a more abstract topic and a longer speaking target.", "items": [{"a": "Introducing a complex topic", "c": "The question of whether success brings happiness is a complicated one."}, {"a": "Presenting a nuanced view", "c": "It's not simply yes or no — it depends on how we define success."}, {"a": "Using a hypothetical", "c": "Imagine someone who has everything but no time for family."}, {"a": "Bringing in a real example", "c": "Consider a case where a person achieves their dream job but feels empty."}, {"a": "Drawing a conclusion", "c": "Ultimately, I believe fulfillment matters more than achievement alone."}, {"a": "Closing strongly", "c": "That is the view I hold, and I welcome any challenge to it."}], "tip": "For abstract topics, pause after each main idea to let your listener absorb it.", "speaking": "Speak for two to three minutes on: 'Does success guarantee happiness?' Use at least four phrases above.", "quiz": [{"type": "fill", "q": "The question of whether success brings happiness is a ____ one.", "answer": "complicated", "explanation": "Useful phrase: \"The question of whether success brings happiness is a complicated one.\""}, {"type": "fill", "q": "It's not simply yes or no — it depends on how we define ____", "answer": "success.", "explanation": "Useful phrase: \"It's not simply yes or no — it depends on how we define success.\""}, {"type": "fill", "q": "Imagine someone who has ____ but no time for family.", "answer": "everything", "explanation": "Useful phrase: \"Imagine someone who has everything but no time for family.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Bringing in a real example\"?", "options": ["Consider a case where a person achieves their dream job but feels empty.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Consider a case where a person achieves their dream job but feels empty."}, {"type": "mcq", "q": "Which phrase best fits: \"Drawing a conclusion\"?", "options": ["Ultimately, I believe fulfillment matters more than achievement alone.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Ultimately, I believe fulfillment matters more than achievement alone."}, {"type": "mcq", "q": "Which phrase best fits: \"Closing strongly\"?", "options": ["That is the view I hold, and I welcome any challenge to it.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "That is the view I hold, and I welcome any challenge to it."}]}, {"id": 56, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Job Interview Practice", "focus": "Speaking confidently under pressure", "type": "fluency", "intro": "Interviews are a real-life test of fluency under pressure — this level prepares you directly for that.", "items": [{"a": "Answering 'Tell me about yourself'", "c": "I'm someone who is passionate about learning and always looking to grow."}, {"a": "Describing a strength", "c": "One of my key strengths is my ability to stay calm under pressure."}, {"a": "Describing a weakness honestly", "c": "I sometimes take on too much, but I'm learning to prioritize better."}, {"a": "Explaining why you want the job", "c": "I'm drawn to this role because it matches both my skills and my interests."}, {"a": "Asking a question at the end", "c": "Could you tell me more about the team I'd be working with?"}, {"a": "Closing an interview", "c": "Thank you for this opportunity — I really enjoyed our conversation."}], "tip": "Sit up straight and smile slightly while speaking — it genuinely changes the warmth of your voice.", "speaking": "Answer 'Tell me about yourself' out loud for one full minute, without stopping.", "quiz": [{"type": "fill", "q": "I'm someone who is ____ about learning and always looking to grow.", "answer": "passionate", "explanation": "Useful phrase: \"I'm someone who is passionate about learning and always looking to grow.\""}, {"type": "fill", "q": "One of my key ____ is my ability to stay calm under pressure.", "answer": "strengths", "explanation": "Useful phrase: \"One of my key strengths is my ability to stay calm under pressure.\""}, {"type": "fill", "q": "I sometimes take on too much, but I'm learning to ____ better.", "answer": "prioritize", "explanation": "Useful phrase: \"I sometimes take on too much, but I'm learning to prioritize better.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Explaining why you want the job\"?", "options": ["I'm drawn to this role because it matches both my skills and my interests.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "I'm drawn to this role because it matches both my skills and my interests."}, {"type": "mcq", "q": "Which phrase best fits: \"Asking a question at the end\"?", "options": ["Could you tell me more about the team I'd be working with?", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Could you tell me more about the team I'd be working with?"}, {"type": "mcq", "q": "Which phrase best fits: \"Closing an interview\"?", "options": ["Thank you for this opportunity — I really enjoyed our conversation.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Thank you for this opportunity — I really enjoyed our conversation."}]}, {"id": 57, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Describing Experiences", "focus": "Vivid, detailed storytelling", "type": "fluency", "intro": "This level challenges you to describe experiences in rich detail, using senses and emotion.", "items": [{"a": "Setting a scene", "c": "It was a cold, quiet morning when we set off on our journey."}, {"a": "Describing a feeling", "c": "I remember feeling a strange mix of excitement and fear."}, {"a": "Using sensory detail", "c": "The smell of fresh bread filled the entire street."}, {"a": "Describing people", "c": "She had a warm smile that put everyone at ease."}, {"a": "Adding a reflection", "c": "That experience taught me to appreciate small moments."}, {"a": "Wrapping up", "c": "Even now, I think back on that day with a smile."}], "tip": "Use your voice like an instrument — soften it for calm moments, raise it for exciting ones.", "speaking": "Describe your most memorable trip or day in vivid detail for two minutes.", "quiz": [{"type": "fill", "q": "It was a cold, quiet morning when we set off on our ____", "answer": "journey.", "explanation": "Useful phrase: \"It was a cold, quiet morning when we set off on our journey.\""}, {"type": "fill", "q": "I remember feeling a strange mix of ____ and fear.", "answer": "excitement", "explanation": "Useful phrase: \"I remember feeling a strange mix of excitement and fear.\""}, {"type": "fill", "q": "The smell of fresh bread filled the entire ____", "answer": "street.", "explanation": "Useful phrase: \"The smell of fresh bread filled the entire street.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Describing people\"?", "options": ["She had a warm smile that put everyone at ease.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "She had a warm smile that put everyone at ease."}, {"type": "mcq", "q": "Which phrase best fits: \"Adding a reflection\"?", "options": ["That experience taught me to appreciate small moments.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "That experience taught me to appreciate small moments."}, {"type": "mcq", "q": "Which phrase best fits: \"Wrapping up\"?", "options": ["Even now, I think back on that day with a smile.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Even now, I think back on that day with a smile."}]}, {"id": 58, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Discussing News & Current Events", "focus": "Speaking about the wider world", "type": "fluency", "intro": "Talking confidently about current events is a strong sign of advanced fluency and general knowledge.", "items": [{"a": "Introducing a topic", "c": "Have you been following the news about renewable energy?"}, {"a": "Summarizing an issue", "c": "From what I understand, many countries are shifting toward solar power."}, {"a": "Giving your view", "c": "Personally, I think this shift is long overdue."}, {"a": "Considering different sides", "c": "Of course, there are economic challenges involved too."}, {"a": "Predicting the future", "c": "I expect this trend to continue over the next decade."}, {"a": "Inviting discussion", "c": "What do you think the biggest challenge will be?"}], "tip": "When discussing serious topics, keep your pace measured and your tone thoughtful, not rushed.", "speaking": "Summarize and give your opinion on a real current event for two minutes.", "quiz": [{"type": "fill", "q": "Have you been ____ the news about renewable energy?", "answer": "following", "explanation": "Useful phrase: \"Have you been following the news about renewable energy?\""}, {"type": "fill", "q": "From what I ____, many countries are shifting toward solar power.", "answer": "understand", "explanation": "Useful phrase: \"From what I understand, many countries are shifting toward solar power.\""}, {"type": "fill", "q": "____, I think this shift is long overdue.", "answer": "Personally", "explanation": "Useful phrase: \"Personally, I think this shift is long overdue.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Considering different sides\"?", "options": ["Of course, there are economic challenges involved too.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Of course, there are economic challenges involved too."}, {"type": "mcq", "q": "Which phrase best fits: \"Predicting the future\"?", "options": ["I expect this trend to continue over the next decade.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "I expect this trend to continue over the next decade."}, {"type": "mcq", "q": "Which phrase best fits: \"Inviting discussion\"?", "options": ["What do you think the biggest challenge will be?", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "What do you think the biggest challenge will be?"}]}, {"id": 59, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Presentation Skills", "focus": "Speaking to an audience", "type": "fluency", "intro": "Presenting to a group is one of the most demanding speaking tasks — this level trains you for it directly.", "items": [{"a": "Opening a presentation", "c": "Good morning everyone, and thank you for being here today."}, {"a": "Stating your purpose", "c": "Today, I'm going to talk about three key ideas."}, {"a": "Signposting", "c": "First, let's look at the background. Then, I'll explain the results."}, {"a": "Emphasizing a key point", "c": "This next point is especially important, so please pay close attention."}, {"a": "Handling a question", "c": "That's a great question — let me address that."}, {"a": "Closing a presentation", "c": "To sum up, these three points show why this matters. Thank you."}], "tip": "Pause for two full seconds after your opening line — it builds calm authority.", "speaking": "Deliver a three-minute presentation on any topic you know well, using the structure above.", "quiz": [{"type": "fill", "q": "Good morning ____, and thank you for being here today.", "answer": "everyone", "explanation": "Useful phrase: \"Good morning everyone, and thank you for being here today.\""}, {"type": "fill", "q": "Today, I'm going to talk about three key ____", "answer": "ideas.", "explanation": "Useful phrase: \"Today, I'm going to talk about three key ideas.\""}, {"type": "fill", "q": "First, let's look at the ____ Then, I'll explain the results.", "answer": "background.", "explanation": "Useful phrase: \"First, let's look at the background. Then, I'll explain the results.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Emphasizing a key point\"?", "options": ["This next point is especially important, so please pay close attention.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "This next point is especially important, so please pay close attention."}, {"type": "mcq", "q": "Which phrase best fits: \"Handling a question\"?", "options": ["That's a great question — let me address that.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "That's a great question — let me address that."}, {"type": "mcq", "q": "Which phrase best fits: \"Closing a presentation\"?", "options": ["To sum up, these three points show why this matters. Thank you.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "To sum up, these three points show why this matters. Thank you."}]}, {"id": 60, "stage": "Stage 6 · Fluency & Confidence", "stageName": "Stage 6 · Fluency & Confidence", "title": "Capstone: Free Speaking", "focus": "Your final fluency challenge", "type": "fluency", "intro": "Congratulations on reaching the final level. This capstone brings together everything: vocabulary, grammar, idioms, and confident delivery.", "items": [{"a": "Opening naturally", "c": "So, I wanted to share a few thoughts today about my journey."}, {"a": "Reflecting on growth", "c": "When I started, I could barely put a full sentence together."}, {"a": "Sharing a challenge overcome", "c": "The hardest part, honestly, was not being afraid to make mistakes."}, {"a": "Expressing pride", "c": "Looking back, I'm genuinely proud of how far I've come."}, {"a": "Giving advice to others", "c": "If I could tell a beginner one thing, it would be: just keep speaking."}, {"a": "Closing with confidence", "c": "I'm ready to keep using English fluently, every single day."}], "tip": "This is your victory lap — speak slowly, clearly, and with a genuine smile in your voice.", "speaking": "Speak for three to five minutes, completely freely, about your English-learning journey and what's next for you. Record it — this is your 'before and after' proof of progress.", "quiz": [{"type": "fill", "q": "So, I wanted to share a few ____ today about my journey.", "answer": "thoughts", "explanation": "Useful phrase: \"So, I wanted to share a few thoughts today about my journey.\""}, {"type": "fill", "q": "When I started, I could barely put a full sentence ____", "answer": "together.", "explanation": "Useful phrase: \"When I started, I could barely put a full sentence together.\""}, {"type": "fill", "q": "The hardest part, honestly, was not being afraid to make ____", "answer": "mistakes.", "explanation": "Useful phrase: \"The hardest part, honestly, was not being afraid to make mistakes.\""}, {"type": "mcq", "q": "Which phrase best fits: \"Expressing pride\"?", "options": ["Looking back, I'm genuinely proud of how far I've come.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "Looking back, I'm genuinely proud of how far I've come."}, {"type": "mcq", "q": "Which phrase best fits: \"Giving advice to others\"?", "options": ["If I could tell a beginner one thing, it would be: just keep speaking.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "If I could tell a beginner one thing, it would be: just keep speaking."}, {"type": "mcq", "q": "Which phrase best fits: \"Closing with confidence\"?", "options": ["I'm ready to keep using English fluently, every single day.", "I don't know anything.", "Maybe, whatever, I guess so.", "No comment at all."], "answer": 0, "explanation": "I'm ready to keep using English fluently, every single day."}]}];
